const SOURCES = {
  "privacy": "import 'package:flutter/material.dart';\n\nclass PrivacyPolicyScreen extends StatelessWidget {\n  const PrivacyPolicyScreen({super.key, this.onClose});\n\n  final VoidCallback? onClose;\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      backgroundColor: Colors.black,\n      appBar: AppBar(\n        backgroundColor: Colors.black,\n        foregroundColor: Colors.white,\n        surfaceTintColor: Colors.transparent,\n        title: const Text('プライバシーポリシー'),\n        leading: IconButton(\n          icon: const Icon(Icons.close),\n          onPressed: onClose ?? () => Navigator.of(context).pop(),\n        ),\n      ),\n      body: const SafeArea(\n        child: SingleChildScrollView(\n          padding: EdgeInsets.symmetric(horizontal: 24, vertical: 20),\n          child: _PrivacyContent(),\n        ),\n      ),\n    );\n  }\n}\n\nclass _PrivacyContent extends StatelessWidget {\n  const _PrivacyContent();\n\n  static const _titleStyle = TextStyle(\n    fontSize: 18,\n    fontWeight: FontWeight.w900,\n    height: 1.5,\n  );\n\n  static const _headingStyle = TextStyle(\n    fontSize: 15,\n    fontWeight: FontWeight.w700,\n    height: 1.7,\n  );\n\n  static const _subheadingStyle = TextStyle(\n    fontSize: 13,\n    fontWeight: FontWeight.w700,\n    height: 1.7,\n  );\n\n  static const _bodyStyle = TextStyle(\n    fontSize: 13,\n    height: 1.9,\n    color: Colors.white,\n  );\n\n  static const String _policyText = r'''# Sharemarium プライバシーポリシー\n\n伊能龍之介（以下「運営者」といいます。）は、運営者が提供する読書レビューSNS「Sharemarium」（以下「本サービス」といいます。）における利用者に関する情報を、以下のとおり取り扱います。\n\n---\n\n## 第1条（適用）\n\n1. 本プライバシーポリシーは、本サービスにおける個人情報その他の利用者に関する情報の取扱いに適用されます。\n\n2. 本サービスと連携する外部サービスについては、当該外部サービスの利用規約、プライバシーポリシーその他の規定も適用されます。\n\n3. 利用者の端末から外部事業者へ送信される情報については、本プライバシーポリシーのほか、「外部送信に関する公表事項」において公表します。\n\n---\n\n## 第2条（運営者に関する情報）\n\n本サービスにおいて個人情報を取り扱う事業者は、次のとおりです。\n\n**事業者名**\n伊能龍之介\n\n**住所**\n運営者の住所は、本人から請求があった場合、法令に従い遅滞なく開示します。住所の開示を希望する場合は、第15条のお問い合わせ窓口から請求してください。\n\n---\n\n## 第3条（取得する情報）\n\n運営者は、本サービスの提供にあたり、次の情報を取得することがあります。\n\n### 1. 利用登録及び本人確認に関する情報\n\n* 氏名\n* 表示名\n* ユーザーネーム\n* 公開用のユーザーID\n* 生年月日\n* 電話番号\n* 電話番号認証の結果\n* 個人情報変更用パスワードのハッシュ値\n* アカウント識別子\n* Supabase上のUID\n* 管理者によるアカウント削除後の不正な再登録を防止するため、氏名、生年月日及びメールアドレス又は電話番号の組み合わせから秘密鍵を用いて作成した照合値\n* 認証provider\n* 登録日時\n* 最終ログイン日時\n* 利用規約及びプライバシーポリシーへの同意日時\n* 同意又は確認した利用規約、プライバシーポリシー、コミュニティガイドライン、権利侵害・通報ポリシー及び外部送信に関する公表事項のバージョン\n* 未成年者が法定代理人の同意を得た旨の申告\n* その他、利用登録、本人確認及び不正利用防止に必要な情報\n\n### 2. 外部サービスとの連携により取得する情報\n\n利用者がX又はGoogleを利用して登録又はログインする場合、運営者は、利用者が当該外部サービス上で許可した範囲で、次の情報を取得することがあります。Facebook、Apple、Discordその他の認証方法は、各認証方法が実際に有効化された場合に本項を適用します。\n\n* 外部サービス上の利用者識別子\n* ユーザー名\n* 公開用のユーザーID\n* プロフィール画像\n* メールアドレス\n* 認証に必要な情報\n* その他、利用者が外部サービスからの提供を許可した情報\n\n運営者は、外部サービスのログインパスワードを取得しません。\n\n外部サービスによるログインでは、各サービスが本サービス向けに発行する利用者識別子をSupabase Authに保存します。表示名、プロフィール画像及びメールアドレスは、利用者が各外部サービス上で提供を許可し、当該サービスから提供された場合に限り取得します。\n\n### 3. プロフィールに関する情報\n\n* プロフィール画像\n* 自己紹介文\n* ユーザー名\n* 公開用のユーザーID\n* その他、利用者がプロフィールに登録した情報\n\n### 4. 本サービス上の活動に関する情報\n\n* レビュー\n* 書籍に対する評価\n* My 本棚及び読書記録\n* 読了、読書中及び「読みたい！」作品等の登録情報\n* リアクション及び「読みたい！」の種類、対象となる投稿、登録日時並びに投稿別の登録数\n* フォロー及びフォロワー情報\n* フォローリクエスト、その承認又は拒否及びフォロー解除に関する情報\n* ブロック及びアカウントの公開・非公開設定\n* アプリ内通知の内容、既読状態及び通知日時\n* 返信本文、返信先となる投稿又は返信の識別情報、返信の親子関係、返信日時、ネタバレ設定及び返信の表示状態\n* 返信機能、「読みたい！」、お気に入りの登録上限、ページカラーの選択範囲その他の限定機能を利用できるかを判定するための利用権限、試験利用又は個別許可に関する情報\n* ページカラーの解禁判定に用いるレビュー投稿件数、解禁可能数、選択して解禁した色及び解禁日時\n* 通報及び異議申立てに関する情報\n* ネタバレ設定\n* 投稿した文章\n* 書籍検索の際に入力した検索語（検索処理のため外部事業者へ送信されますが、本サービスの利用者別検索履歴としては保存しません。）\n* ユーザー検索の際に入力した検索語（ユーザー名及び公開用のユーザーIDとの照合にのみ使用し、利用者別検索履歴としては保存しません。）\n* その他、本サービス上で利用者が入力、投稿、保存又は操作した情報\n\n### 5. お問い合わせ等に関する情報\n\n* お問い合わせ内容\n* 通報内容\n* 通報理由、任意の補足、対象投稿又は対象返信の識別情報及び記録並びに対応状況\n* 権利侵害に関する申出の内容\n* 異議申立ての内容\n* 運営者とのやり取り\n* 本人確認のために提出された情報及び資料\n* 対応結果\n* その他、お問い合わせ等への対応に必要な情報\n\n本人確認書類の提出を求める場合、運営者は、確認に必要な範囲に限って取得し、確認後は保存する必要がある場合を除き、速やかに削除又はマスキング等の処理を行います。\n\n### 6. 端末、通信及び利用状況に関する情報\n\n* IPアドレス\n* Cookieその他の識別子\n* 広告識別子\n* 端末情報\n* OSの種類及びバージョン\n* ブラウザの種類及びバージョン\n* アプリの種類及びバージョン\n* 使用言語\n* アクセス日時\n* 閲覧したページ又は画面\n* リファラー\n* 操作履歴\n* ログイン履歴\n* 通信記録\n* エラー情報\n* クラッシュ情報\n* 不正利用の検知に必要な情報\n* その他、本サービスの利用状況及び動作状況に関する情報\n\n### 7. 違反対応及び安全管理に関する情報\n\n* 利用規約又はコミュニティガイドラインへの違反履歴\n* 警告、投稿削除、利用制限及びアカウント停止等の措置履歴\n* 不正アクセス又は不正利用の疑いに関する情報\n* セキュリティ上の調査記録\n* 通報者及び対象利用者から提出された情報\n* その他、本サービスの安全な運営に必要な情報\n\n---\n\n## 第4条（情報の取得方法）\n\n運営者は、次の方法により利用者に関する情報を取得します。\n\n1. 利用者が本サービス上で直接入力又は投稿する方法\n2. 利用者が本サービスを利用する際に自動的に取得する方法\n3. 利用者が連携を許可した外部サービスから取得する方法\n4. お問い合わせ、通報、異議申立てその他の連絡を通じて取得する方法\n5. 法令に基づき、又は適法に第三者から提供を受ける方法\n6. その他、適法かつ公正な方法\n\n本サービスでは、利用登録、認証、データベース、同意履歴、お問い合わせ及び退会処理のためにSupabaseを利用します。これに伴い、氏名、生年月日、電話番号、ユーザーネーム、公開用のユーザーID、メールアドレス、UID、認証provider、アカウント作成日時、最終ログイン日時、認証記録、個人情報変更用パスワードのハッシュ値その他本サービスの提供に必要な情報がSupabaseを通じて取得、保存又は処理されます。氏名、生年月日及び電話番号は公開プロフィールから分離して保存します。個人情報変更用パスワードは復元できない形式に変換して保存し、運営者を含めて元の文字列を閲覧できないようにします。\n\n運営者は、偽りその他不正な手段により個人情報を取得しません。\n\n---\n\n## 第5条（利用目的）\n\n運営者は、取得した情報を、次の目的で利用します。\n\n### 1. 本サービスの提供及び運営\n\n* 利用登録を受け付けるため\n* アカウントを作成及び管理するため\n* 利用者を認証するため\n* 登録情報を確認及び管理するため\n* 電話番号認証を導入した場合に電話番号を確認するため\n* 外部サービスを利用した登録及びログインを提供するため\n* 書籍情報、レビュー、My 本棚、お気に入り、「読みたい！」作品、リアクション、フォロー、フォローリクエスト及びブロックその他の機能を提供するため\n* 利用権限、試験利用又は個別許可の状態に応じて、返信、「読みたい！」、お気に入りの登録上限、ページカラーの選択範囲その他の限定機能を提供するため\n* レビューの投稿件数に応じたページカラーの解禁状況を判定し、一度解禁した色を継続して提供するため\n* ユーザー名及び公開用のユーザーIDによるユーザー検索機能を提供するため\n* 返信の投稿、スレッド表示、閲覧権限の制御及び返信機能の利用権限を判定するため\n* リアクション、「読みたい！」、返信、フォロー、フォローリクエスト及びフォロー中の登録利用者による新規投稿に関するアプリ内通知を提供するため\n* アカウントの公開・非公開、ネタバレ表示その他の設定を反映するため\n* 本サービス上の情報を保存及び表示するため\n\n### 2. 年齢確認及び青少年保護\n\n* 利用者の年齢を確認するため\n* 年齢に応じて表示される書籍情報及び投稿コンテンツを制限するため\n* 18歳未満の利用者に年齢制限対象コンテンツが表示されることを防止するため\n* 未成年者による利用について、法定代理人の同意状況を確認するため\n* 青少年保護のための安全対策を実施及び改善するため\n\n### 3. 利便性及びサービス品質の向上\n\n* 利用状況を分析するため\n* 利用者の興味、関心及び利用傾向に応じた情報を表示するため\n* 検索機能、表示機能その他の機能を改善するため\n* 新しい機能及びサービスを企画、開発及び検証するため\n* 不具合、エラー及び障害を調査、修正及び防止するため\n* 本サービスの利用状況に関する統計情報を作成するため\n\n### 4. 広告の配信及び測定\n\n* 本サービス上に広告を表示するため\n* 広告の配信状況及び広告効果を測定するため\n* 不正な広告表示又はクリックを検知及び防止するため\n* 法令、利用者の設定及び必要な同意に応じて、利用者の興味又は関心に関連する広告を表示するため\n\n### 5. 安全管理及び不正利用防止\n\n* 不正登録及び複数アカウントの不正利用を防止するため\n* 利用停止又は管理者によるアカウント削除を受けた者による不正な再登録を防止するため\n* なりすまし、スパム、ボット、スクレイピングその他の不正利用を検知及び防止するため\n* 利用規約及びコミュニティガイドラインへの違反を調査するため\n* 投稿コンテンツの安全性及び適切性を確認するため\n* 不正アクセス、サイバー攻撃その他のセキュリティ上の問題を検知、調査及び防止するため\n* 利用者、運営者又は第三者の権利、財産及び安全を保護するため\n\n### 6. お問い合わせ、通報及び権利侵害対応\n\n* お問い合わせに回答するため\n* 通報及び権利侵害に関する申出を確認及び処理するため\n* 投稿者その他の関係者から意見又は資料を取得するため\n* 異議申立てを確認及び処理するため\n* 本人確認を行うため\n* 対応内容を記録し、同様の問題の再発を防止するため\n\n### 7. 連絡及び通知\n\n* 本サービスに関する重要な連絡を行うため\n* 利用規約、プライバシーポリシーその他の規程の変更を通知するため\n* メンテナンス、障害及びサービス終了等を通知するため\n* セキュリティ上の注意事項を通知するため\n* 利用者から希望又は同意がある場合に、案内等を送信するため\n\n### 8. 法令及び紛争への対応\n\n* 法令上の義務を履行するため\n* 裁判所、捜査機関その他の公的機関からの適法な要請に対応するため\n* 訴訟、紛争、苦情及び法的請求に対応するため\n* 運営者又は第三者の権利を行使及び保護するため\n* 不正利用等に関する証拠を保存するため\n\n### 9. 前各号に付随する目的\n\n前各号に掲げる目的に合理的に関連し、利用者が通常予測できる範囲の目的のために利用します。\n\n---\n\n## 第6条（利用目的の変更）\n\n1. 運営者は、変更前の利用目的と合理的な関連性を有すると認められる範囲で、利用目的を変更することがあります。\n\n2. 利用目的を変更した場合、運営者は、変更後の利用目的を本サービス上への掲載その他適切な方法により公表又は通知します。\n\n3. 法令上、利用者の同意が必要となる変更については、変更後の利用を開始する前に必要な同意を取得します。\n\n---\n\n## 第7条（投稿コンテンツ及び公開情報）\n\n1. 利用者がアカウントを公開設定にして投稿したレビュー、返信、プロフィール、My 本棚、お気に入り、「読みたい！」作品、リアクションその他の情報は、登録していない者を含む第三者から閲覧される場合があります。また、公開アカウントのフォロー及びフォロワーの一覧並びに投稿へリアクション又は「読みたい！」を行った登録利用者の一覧は、他の登録利用者から閲覧される場合があります。\n\n1-1. 返信には、返信者のプロフィール画像、ユーザー名、公開用のユーザーID、返信日時及び返信先との関係が表示される場合があります。返信は対象となる投稿の閲覧権限に従って表示され、対象投稿の削除、非表示、公開範囲の変更、ブロック関係その他の事情により表示されなくなることがあります。\n\n1-2. ユーザー名及び公開用のユーザーIDは、アカウントの公開・非公開設定にかかわらず、他の登録利用者によるユーザー検索の対象となります。氏名、メールアドレス、電話番号及び生年月日は、ユーザー検索の対象となりません。\n\n2. 公開された情報は、検索エンジンの検索結果に表示され、第三者に共有、保存、転載又は引用される場合があります。\n\n3. 利用者は、自己又は第三者の住所、電話番号、メールアドレス、勤務先、学校、正確な位置情報その他公開を望まない情報を投稿しないよう注意してください。\n\n4. 利用者が第三者に関する個人情報を投稿する場合は、当該第三者の同意を取得するなど、適法に投稿するために必要な対応を行うものとします。\n\n5. 鍵アカウントの設定は、本サービス上における表示範囲を制御するものであり、情報の秘密性又は第三者による取得を完全に保証するものではありません。\n\n6. 運営者は、本サービスの提供、障害対応、不正利用調査、通報対応及び法令遵守に必要な範囲で、鍵アカウントの情報を取り扱うことがあります。\n\n7. 鍵アカウントの投稿、My 本棚、お気に入り及び「読みたい！」作品は、本人及び承認済みフォロワーに表示されます。フォローリクエストが拒否若しくは取り消された場合又は鍵アカウントとのフォロー関係が解除された場合、当該鍵アカウントの投稿等の表示が制限されます。また、当事者の一方が他方をブロックした場合、両者間の表示及び交流が制限されます。ただし、すでに第三者が保存又は共有した情報の消去を保証するものではありません。\n8. 鍵アカウントのフォロー及びフォロワーの一覧は、当該アカウント本人にのみ表示されます。\n\n---\n\n## 第8条（Cookie等及び広告）\n\n1. 運営者は、本サービスの提供、認証、設定の保存、利用状況の分析、不正利用防止及び広告配信等のため、Cookie、広告識別子その他の技術を利用することがあります。\n\n2. 利用者は、ブラウザ又は端末の設定により、Cookie又は広告識別子の利用を制限又は無効化できる場合があります。\n\n3. Cookie等を無効化した場合、本サービスの一部機能が利用できず、又は正常に動作しない場合があります。\n\n4. 本サービスでは、広告掲載の対象となるWeb画面で、忍者ツールズ株式会社が提供する広告配信サービス「忍者AdMax」を利用しています。広告枠は、本サービスの広告配信条件を満たす画面及び利用者に限って表示します。\n\n5. 忍者AdMaxの広告が読み込まれる場合、同社及び広告の配信に関与する事業者が、IPアドレス、閲覧ページのURL、リファラー、アクセス日時、ブラウザ及び端末に関する情報、Cookieその他の識別子、広告の表示・操作に関する情報等を取得し、広告の配信、最適化、効果測定及び不正防止等に利用する場合があります。送信先、送信される情報及び利用目的は「外部送信に関する公表事項」に記載します。\n\n6. 忍者ツールズ株式会社のCookie等の取扱いと設定方法は https://corp.ninja.co.jp/privacy/cookie/ 、広告に関する業務提携先の公表情報は https://corp.ninja.co.jp/privacy/tieup/ を参照してください。利用者はブラウザの設定でCookieを制限できる場合がありますが、広告配信及び一部機能に影響することがあります。\n\n7. Googleによる広告配信（Google AdSense）は、現在の広告配信には使用していません。今後導入する場合、Googleを含む第三者配信事業者がCookieを利用し、過去のアクセス情報に基づいて広告を配信する場合があります。その際、Googleが広告Cookieを使用すると、Google及びそのパートナーは本サービス又は他のウェブサイトへのアクセス情報に基づいて広告を表示することがあります。\n\n8. Google広告を将来利用する場合、Googleの広告設定（https://adssettings.google.com/）からGoogleによるパーソナライズド広告を制限又は無効化できます。第三者広告事業者が提供する設定又は https://www.aboutads.info/ で無効化できる場合もあります。\n\n9. 広告のパーソナライズを制限していても、閲覧内容やおおよその地域等に基づく広告が表示されることがあります。適用法令により別途同意等が必要な場合は、必要な対応を行います。\n\n10. 利用者の端末から外部事業者へ送信される情報、送信先及び利用目的の詳細は、「外部送信に関する公表事項」に記載します。\n\n---\n\n## 第9条（第三者への提供）\n\n1. 運営者は、次の場合を除き、あらかじめ本人の同意を得ることなく、個人データを第三者に提供しません。\n\n   1. 法令に基づく場合\n   2. 人の生命、身体又は財産の保護のために必要であり、本人の同意を得ることが困難である場合\n   3. 公衆衛生の向上又は児童の健全な育成の推進のために特に必要であり、本人の同意を得ることが困難である場合\n   4. 国の機関、地方公共団体又はその委託を受けた者が法令上の事務を遂行することに協力する必要があり、本人の同意を得ることにより当該事務の遂行に支障を及ぼすおそれがある場合\n   5. その他、個人情報保護法その他の法令により認められる場合\n\n2. 次の場合、提供先は個人情報保護法上の第三者に該当しないことがあります。\n\n   1. 利用目的の達成に必要な範囲で、個人データの取扱いの全部又は一部を委託する場合\n   2. 合併、事業譲渡、法人化、相続その他の事由により、本サービスに関する事業及び個人データが承継される場合\n   3. 法令に定める共同利用を行う場合\n\n3. 運営者は、本人の同意を得ないオプトアウト方式による個人データの第三者提供を、原則として行いません。\n\n4. 運営者は、利用者の個人データを販売しません。\n\n---\n\n## 第10条（業務委託）\n\n1. 運営者は、利用目的の達成に必要な範囲で、次の業務等を外部事業者へ委託することがあります。\n\n   * システムの開発、運用及び保守\n   * データの保存及び処理\n   * 利用者認証\n   * 電話番号認証\n   * アクセス解析\n   * 広告配信及び広告効果測定\n   * エラー及び障害の解析\n   * お問い合わせ対応\n   * セキュリティ対策\n   * その他本サービスの運営に必要な業務\n\n2. 運営者は、委託先を適切に選定し、契約その他の方法により必要な事項を定め、委託先における個人データの取扱いを必要かつ適切に監督します。\n\n3. 委託先には、利用目的の達成に必要な範囲の情報のみを取り扱わせます。\n\n4. 主な委託先として、Supabase, Inc.が提供するSupabase Auth、Database及びEdge Functions並びにVercel Inc.が提供するWebホスティング及び配信サービスを利用します。Supabaseは、利用者認証、アカウント情報、投稿、返信、通知及び限定機能の利用権限等の保存又は処理、同意履歴及びお問い合わせの保存、退会処理、ログ管理、不正利用防止並びにセキュリティ確保のために利用します。Vercelは、本サービスのWebページ及び静的ファイルの配信、障害対応並びにセキュリティ確保のために利用します。\n\n5. 書籍検索及び書籍情報の取得には楽天グループ株式会社の楽天ウェブサービス、書影の最適化及び配信にはimages.weserv.nl、書籍の購入先へのリンクには楽天アフィリエイト（利用開始時のみ）、Googleアカウント認証及びWebフォントの配信にはGoogle LLCのサービスを利用します。Web画面の広告配信には忍者ツールズ株式会社の「忍者AdMax」を利用しています。Google AdSenseによる広告配信は現時点では行っていません。各事業者へ送信される情報及び利用目的の詳細は、「外部送信に関する公表事項」に記載します。\n\n---\n\n## 第11条（外国における情報の取扱い）\n\n1. 本サービスでは、外国に所在する事業者が提供する認証、クラウド、アクセス解析、広告配信その他のサービスを利用する場合があります。\n\n2. これに伴い、利用者に関する情報が、日本国外に所在するサーバーで保存若しくは処理され、又は外国に所在する事業者によって取り扱われる場合があります。\n\n3. 運営者は、外国にある第三者へ個人データを提供する場合、個人情報保護法その他の法令に従い、必要な同意の取得、相当措置の確認、情報提供その他必要な対応を行います。\n\n4. 外国に所在する委託先等に個人データを取り扱わせる場合、運営者は、当該外国の個人情報保護制度その他の外的環境を把握し、必要かつ適切な安全管理措置及び監督を行います。\n\n5. 利用する外部サービス及び外部送信に関する事項は、本プライバシーポリシー及び「外部送信に関する公表事項」において、可能な範囲で公表します。\n\n---\n\n## 第12条（安全管理措置）\n\n運営者は、個人データへの不正アクセス、漏えい、滅失、毀損、改ざんその他の事故を防止するため、必要かつ適切な安全管理措置を講じます。\n\n安全管理措置には、主に次のものが含まれます。\n\n### 1. 基本方針及び取扱ルール\n\n* 個人情報の適正な取扱いに関する基本方針の策定\n* 取得、利用、保存、提供及び削除に関する取扱方法の整備\n* 問題が発生した場合の連絡及び対応手順の整備\n\n### 2. 組織的安全管理措置\n\n* 個人データを取り扱う範囲及び権限の明確化\n* 個人データの取扱状況の確認\n* 漏えい等が発生し、又はそのおそれがある場合の報告及び対応体制の整備\n\n### 3. 人的安全管理措置\n\n* 個人データを取り扱う者に対する必要な教育及び注意喚起\n* 個人データに関する秘密保持及び適正な取扱いの徹底\n\n### 4. 物理的安全管理措置\n\n* 個人データを取り扱う端末及び媒体の適切な管理\n* 端末及び媒体の盗難、紛失及び不正利用の防止\n* 個人データを削除する場合の適切な処理\n\n### 5. 技術的安全管理措置\n\n* アクセス権限の制限及び認証\n* 通信の暗号化その他の保護\n* 不正アクセス及びマルウェア等への対策\n* システムの脆弱性及び安全性の確認\n* 操作記録及びアクセス状況の確認\n* 認証情報及び秘密情報の適切な管理\n\n### 6. 外的環境の把握\n\n外国において個人データを取り扱う場合、当該外国の個人情報保護制度その他の外的環境を把握した上で、必要な安全管理措置を実施します。\n\n安全管理措置の詳細については、セキュリティに支障を及ぼすおそれのある情報を除き、本人から請求があった場合に、合理的な範囲で遅滞なく回答します。\n\n---\n\n## 第13条（漏えい等への対応）\n\n1. 運営者は、個人データの漏えい、滅失、毀損その他の事故が発生し、又は発生したおそれがある場合、事実関係の調査、被害拡大防止、原因究明及び再発防止その他必要な対応を行います。\n\n2. 法令上、個人情報保護委員会への報告又は本人への通知が必要となる場合、運営者は、法令に従って報告又は通知を行います。\n\n3. 犯罪又は不正アクセス等が疑われる場合、運営者は、必要に応じて警察その他の関係機関へ相談又は通報します。\n\n---\n\n## 第14条（保存期間及び削除）\n\n1. 運営者は、取得した個人情報その他の利用者に関する情報を、その利用目的の達成に必要な期間に限り保存します。\n\n2. 利用者が本サービスを退会した場合、運営者は、当該利用者の個人情報及びアカウントに紐づく情報を、第4項に定める場合を除き、退会手続の完了日から90日以内に削除し、又は特定の個人との対応関係を復元できない方法により匿名化します。\n\n3. 本サービスの全部が終了した場合、運営者は、利用者の個人情報及び本サービスに関連して保存している情報を、第4項に定める場合を除き、本サービスの終了日から3か月以内に削除し、又は匿名化します。\n\n4. 次の情報については、前2項にかかわらず、それぞれの目的に必要な期間保存することがあります。\n\n   1. 法令により保存が義務付けられている情報\n   2. 訴訟、紛争、苦情、通報又は権利侵害への対応に必要な情報\n   3. 不正利用又はセキュリティ上の事故の調査及び再発防止に必要な情報\n   4. 捜査機関、裁判所その他の公的機関から適法に保存又は提供を求められた情報\n   5. 利用停止又はアカウント削除を受けた者による不正な再登録の防止に必要な情報\n   6. バックアップ媒体から直ちに削除することが技術上困難であり、通常の運用では利用されない状態で保存される情報\n   7. 統計化又は匿名化され、特定の個人を識別できない情報\n\n5. 退会処理の確認、問い合わせ対応、不正利用若しくはセキュリティ上の問題の調査、紛争対応又は裁判所、警察その他の公的機関からの適法な照会への対応のため、運営者は、元の利用者識別子、ユーザー名、公開用のユーザーID、氏名、生年月日、メールアドレス、電話番号、認証方式、退会種別、退会日時、削除処理の成否、削除実行者及び必要最小限の対応履歴を、退会手続又は削除処理から90日間、一般の利用者からアクセスできない領域へ保存します。\n\n6. 裁判所、警察その他の公的機関から適法な保存要請若しくは照会を受けた場合、又は具体的な紛争、通報、権利侵害若しくは不正利用への対応に必要な場合、運営者は、対象となる退会記録に法的保存措置を設定し、前項の期間を超えて必要な期間保存することがあります。保存の必要がなくなった場合、当該措置を解除し、合理的な期間内に削除又は匿名化します。\n\n7. 管理者によるアカウント削除後の不正な再登録を防止するため、運営者は、氏名及び生年月日と、メールアドレス又は電話番号との組み合わせから秘密鍵を用いて作成した、元の情報を復元できない照合値を、アカウント削除日から3年間保存します。この照合値は再登録時の確認以外の目的には使用せず、保存期間の経過後に削除します。利用者自身による通常の退会については、管理者による利用停止又は削除措置を兼ねる場合を除き、この照合値を作成しません。\n\n8. 前2項以外で第4項に基づいて情報を保存する場合、運営者は、当該保存目的に必要な範囲を超えて利用せず、保存する必要がなくなった後、合理的な期間内に削除又は匿名化します。\n\n9. 利用目的を達成し、保存する必要がなくなった情報については、前各項に定める期間の経過前であっても、削除又は匿名化することがあります。\n\n10. 他の利用者による返信、引用又は共有の対象となった投稿コンテンツについては、会話その他の表示を維持するため、投稿者を特定しにくい状態に変更した上で残る場合があります。\n\n11. 退会前に利用者自身が外部へ共有し、又は第三者が保存若しくは転載した情報について、運営者は、当該第三者が保有する情報を削除できない場合があります。\n\n---\n\n## 第15条（保有個人データに関する請求）\n\n1. 本人は、個人情報保護法に基づき、運営者に対し、次の請求等を行うことができます。\n\n   1. 保有個人データの利用目的の通知\n   2. 保有個人データ又は第三者提供記録の開示\n   3. 保有個人データの内容の訂正、追加又は削除\n   4. 保有個人データの利用停止又は消去\n   5. 保有個人データの第三者への提供の停止\n   6. その他法令により認められる請求\n\n2. 請求を行う場合は、本サービス上のお問い合わせフォームから、請求の内容及び本人確認に必要な情報を送信してください。\n\n3. 運営者は、請求者が本人又は適法な代理人であることを確認するため、次の情報又は資料の提出を求めることがあります。\n\n   * アカウントに登録された情報\n   * 電話番号認証\n   * 本人確認書類\n   * 代理権を確認する書類\n   * その他、本人又は代理人であることを確認するために必要な情報\n\n4. 本人確認書類を取得した場合、運営者は、本人確認及び法令対応に必要な期間を超えて保存せず、不要となった後、速やかに削除又は適切に処理します。\n\n5. 運営者は、請求を受けた場合、法令に従い、合理的な期間内に対応します。\n\n6. 法令により請求の全部又は一部に応じないことが認められる場合、運営者は、請求に応じないことがあります。この場合、法令上通知が不要とされる場合を除き、その旨及び理由を通知します。\n\n7. 開示等の請求に関する手数料は、原則として無料とします。ただし、書面による交付、郵送その他特別な対応に実費が生じる場合、法令により認められる範囲で、事前に金額を示した上で実費相当額を求めることがあります。\n\n---\n\n## 第16条（未成年者の情報）\n\n1. 未成年者が本サービスを利用する場合、あらかじめ親権者その他の法定代理人に、本プライバシーポリシーの内容を確認してもらい、本サービスの利用及び個人情報の取扱いについて同意を得るものとします。\n\n2. 自らの個人情報の取扱いについて、その結果を十分に理解し判断する能力を有しない利用者については、法定代理人が必要な説明を行い、当該利用者に代わって、又は当該利用者とともに同意手続を行うものとします。\n\n3. 運営者は、未成年者による利用について必要があると合理的に判断した場合、法定代理人の同意を確認するための情報又は資料を求めることがあります。\n\n4. 運営者は、18歳未満の利用者に対し、年齢制限対象コンテンツの表示を制限するため、生年月日その他の年齢に関する情報を利用します。\n\n---\n\n## 第17条（統計情報等の利用）\n\n1. 運営者は、取得した情報を、特定の個人を識別できないように集計又は加工し、統計情報として利用することがあります。\n\n2. 運営者は、法令に従って作成された匿名加工情報又は仮名加工情報を取り扱う場合、当該情報の取扱いに関する法令上の義務を遵守します。\n\n3. 運営者は、統計情報を、本サービスの改善、研究、分析、広報、事業上の説明その他適切な目的で利用し、又は第三者へ提供することがあります。ただし、特定の個人を識別できる状態では提供しません。\n\n---\n\n## 第18条（本プライバシーポリシーの変更）\n\n1. 運営者は、法令の改正、本サービスの内容変更、利用する外部サービスの変更その他必要がある場合、本プライバシーポリシーを変更することがあります。\n\n2. 運営者は、本プライバシーポリシーを変更する場合、変更後の内容及び効力発生日を、本サービス上への掲載その他適切な方法により公表又は通知します。\n\n3. 利用者に重大な影響又は不利益を与える変更については、緊急又はやむを得ない場合を除き、原則として効力発生日の30日前までに公表又は通知します。\n\n4. 法令上、利用者の同意が必要となる変更については、変更後の取扱いを開始する前に、運営者所定の方法で同意を取得します。\n\n---\n\n## 第19条（お問い合わせ窓口）\n\n本プライバシーポリシー、個人情報の取扱い、開示等の請求、苦情、運営者の住所又は安全管理措置に関するお問い合わせは、本サービス上のお問い合わせフォームからご連絡ください。\n\n**個人情報取扱事業者**\n伊能龍之介\n\n**サービス名**\nSharemarium\n\n**お問い合わせ方法**\n本サービス上のお問い合わせフォーム\n\n---\n\n## 改定履歴\n\n**2026年10月17日／バージョン1.12.0**\n\n現在提供していない定期購入サービスに関する表現を削除し、限定機能の判定に用いる情報を、利用権限、試験利用又は個別許可に関する情報として整理しました。また、レビュー投稿件数に応じたページカラーの解禁判定及び解禁状態の維持に用いる情報と利用目的を明確化しました。\n\n**2026年10月12日／バージョン1.11.0**\n\n書籍の購入先リンクをAmazonアソシエイトから楽天アフィリエイトへ変更し、リンク先及び外部送信情報の説明を更新しました。\n現在利用している忍者AdMaxの広告配信、Cookie等による情報取得、外部送信先及びGoogle AdSenseの非稼働状態を明確化しました。\n\n**2026年9月16日／バージョン1.10.0**\nGoogle等の第三者配信事業者によるCookieの利用、Google広告Cookie、過去のアクセス情報に基づく広告配信及びGoogleの広告設定によるパーソナライズド広告の無効化について明確化しました。\n\n**2026年9月4日／バージョン1.9.0**\n\nAmazonアソシエイト・プログラムを利用した書籍の購入先リンクに関する外部サービスの取扱いを追記しました。\n\n**2026年9月2日／バージョン1.8.0**\n「読みたい！」作品、投稿別の登録情報、通知及び反応者一覧の取得項目、利用目的並びに公開範囲を明確化しました。\n\n**2026年8月30日／バージョン1.7.0**\n退会者の本人確認情報及び削除監査情報の90日間保存、自動削除並びに適法な照会等に伴う法的保存措置について、取得情報、利用目的及び保存期間を明確化しました。\n\n**2026年8月30日／バージョン1.6.0**\n限定機能の利用権限に応じたお気に入り登録上限及びページカラー選択範囲の判定に必要な情報と利用目的を明確化しました。\n\n**2026年8月30日／バージョン1.5.0**\nGoogleアカウント認証の提供開始に合わせ、Googleから取得する情報、利用目的及び外部サービスの取扱いを更新しました。\n\n**2026年8月28日／バージョン1.4.0**\n返信のネタバレ設定及びフォロー中の登録利用者による新規投稿通知に関する取得情報と利用目的を明確化しました。\n\n**2026年8月28日／バージョン1.3.0**\n返信単位の通報機能で取得する対象返信の識別情報、返信本文の記録及び対応状況を明確化しました。\n\n**2026年8月27日／バージョン1.2.0**\n返信本文、返信関係、通知及び限定機能の利用権限に関する取得情報、利用目的及び公開範囲を明確化しました。\n\n**2026年8月19日／バージョン1.1.0**\nユーザー検索で照合する公開情報、Supabaseで取り扱う登録情報及び検索語の取扱いを明確化しました。\n\n**2026年7月25日／バージョン1.0.0**\n本ポリシーを制定しました。\n\n---\n\n## 附則\n\n**制定日**\n2026年7月25日\n\n**最終改定日**\n2026年10月17日\n\n**バージョン**\n1.12.0\n\n**運営者**\n伊能龍之介''';\n\n  @override\n  Widget build(BuildContext context) {\n    final blocks = _parseBlocks(_policyText);\n\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.start,\n      children: [\n        for (final block in blocks) ...[\n          if (block.spacingBefore > 0) SizedBox(height: block.spacingBefore),\n          Padding(\n            padding: EdgeInsets.only(left: block.isBullet ? 12 : 0),\n            child: Text(\n              block.text,\n              style: block.style.copyWith(color: Colors.white),\n            ),\n          ),\n        ],\n        const SizedBox(height: 40),\n      ],\n    );\n  }\n\n  static List<_PolicyBlock> _parseBlocks(String source) {\n    final blocks = <_PolicyBlock>[];\n    var previousLineWasEmpty = false;\n\n    for (final rawLine in source.split('\\n')) {\n      final line = rawLine.trim();\n      if (line.isEmpty) {\n        previousLineWasEmpty = true;\n        continue;\n      }\n      if (line == '---') {\n        previousLineWasEmpty = true;\n        continue;\n      }\n\n      final spacing = previousLineWasEmpty ? 12.0 : 2.0;\n      previousLineWasEmpty = false;\n\n      if (line.startsWith('# ')) {\n        blocks.add(\n          _PolicyBlock(\n            text: line.substring(2),\n            style: _titleStyle,\n            spacingBefore: blocks.isEmpty ? 0 : 20,\n          ),\n        );\n      } else if (line.startsWith('## ')) {\n        blocks.add(\n          _PolicyBlock(\n            text: line.substring(3),\n            style: _headingStyle,\n            spacingBefore: blocks.isEmpty ? 0 : 20,\n          ),\n        );\n      } else if (line.startsWith('### ')) {\n        blocks.add(\n          _PolicyBlock(\n            text: line.substring(4),\n            style: _subheadingStyle,\n            spacingBefore: 12,\n          ),\n        );\n      } else if (line.startsWith('**') && line.endsWith('**')) {\n        blocks.add(\n          _PolicyBlock(\n            text: line.substring(2, line.length - 2),\n            style: _subheadingStyle,\n            spacingBefore: spacing,\n          ),\n        );\n      } else if (line.startsWith('* ')) {\n        blocks.add(\n          _PolicyBlock(\n            text: '• ${line.substring(2).replaceAll('**', '')}',\n            style: _bodyStyle,\n            spacingBefore: 0,\n            isBullet: true,\n          ),\n        );\n      } else {\n        blocks.add(\n          _PolicyBlock(\n            text: line.replaceAll('**', ''),\n            style: _bodyStyle,\n            spacingBefore: spacing,\n          ),\n        );\n      }\n    }\n\n    return blocks;\n  }\n}\n\nclass _PolicyBlock {\n  const _PolicyBlock({\n    required this.text,\n    required this.style,\n    required this.spacingBefore,\n    this.isBullet = false,\n  });\n\n  final String text;\n  final TextStyle style;\n  final double spacingBefore;\n  final bool isBullet;\n}\n",
  "terms": "import 'package:flutter/material.dart';\n\nclass TermsScreen extends StatelessWidget {\n  const TermsScreen({super.key, this.onClose});\n\n  final VoidCallback? onClose;\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      backgroundColor: Colors.black,\n      appBar: AppBar(\n        backgroundColor: Colors.black,\n        foregroundColor: Colors.white,\n        surfaceTintColor: Colors.transparent,\n        title: const Text('利用規約'),\n        leading: IconButton(\n          icon: const Icon(Icons.close),\n          onPressed: onClose ?? () => Navigator.of(context).pop(),\n        ),\n      ),\n      body: const SafeArea(\n        child: SingleChildScrollView(\n          padding: EdgeInsets.symmetric(horizontal: 24, vertical: 20),\n          child: _TermsContent(),\n        ),\n      ),\n    );\n  }\n}\n\nclass _TermsContent extends StatelessWidget {\n  const _TermsContent();\n\n  static const _titleStyle = TextStyle(\n    fontSize: 18,\n    fontWeight: FontWeight.w900,\n    height: 1.5,\n  );\n\n  static const _headingStyle = TextStyle(\n    fontSize: 15,\n    fontWeight: FontWeight.w700,\n    height: 1.7,\n  );\n\n  static const _subheadingStyle = TextStyle(\n    fontSize: 13,\n    fontWeight: FontWeight.w700,\n    height: 1.7,\n  );\n\n  static const _bodyStyle = TextStyle(\n    fontSize: 13,\n    height: 1.9,\n    color: Colors.white,\n  );\n\n  static const String _termsText = r'''# Sharemarium 利用規約\n\n本利用規約（以下「本規約」といいます。）は、伊能龍之介（以下「運営者」といいます。）が提供する読書レビューSNS「Sharemarium」（以下「本サービス」といいます。）の利用条件を定めるものです。\n\n利用者は、本規約及び本サービスに適用される各種ルールの内容を確認し、これらに同意した上で本サービスを利用するものとします。\n\n---\n\n## 第1条（適用及び利用契約）\n\n1. 本規約は、本サービスの提供条件及び本サービスの利用に関する運営者と利用者との間の一切の関係に適用されます。\n2. 本規約は、アカウントを登録して本サービスを利用する者だけでなく、アカウントを登録せずに本サービスを閲覧する者にも、本サービスの利用条件として適用されます。\n3. 本サービスへの利用登録を希望する者が、本規約及びプライバシーポリシーを確認し、運営者所定の方法で同意して登録を申請し、登録手続が完了した時点で、当該利用者と運営者との間に、本規約を内容とする利用契約が成立します。\n4. 運営者は、本サービスの利用に関し、コミュニティガイドライン、権利侵害・通報ポリシーその他の規程（以下「個別規程」といいます。）を定めることがあります。\n5. 個別規程は、当該個別規程において本規約の一部を構成する旨を明示した場合、本規約の一部を構成します。\n6. 本規約と個別規程の内容が異なる場合、当該事項について個別規程に明示的に定められた範囲で、個別規程が優先して適用されます。\n7. プライバシーポリシーは、利用者に関する情報の取扱いを定めるものです。外部送信に関する公表事項は、利用者の端末から外部事業者へ送信される情報等を説明するものです。\n8. FAQ、ヘルプページその他の説明資料は、当該資料において利用契約の内容を構成する旨が明示されている場合を除き、本サービスの利用方法を説明するためのものであり、本規約の内容を変更するものではありません。\n\n---\n\n## 第2条（定義）\n\n本規約において使用する用語は、次の各号に定める意味を有します。\n1. 「利用者」とは、本サービスを閲覧又は利用するすべての者をいいます。\n2. 「登録利用者」とは、本規約に同意し、運営者所定の利用登録を完了した者をいいます。\n3. 「アカウント」とは、登録利用者を識別し、本サービスを利用するために作成される登録情報の集合をいいます。\n4. 「書籍情報」とは、書籍の題名、著者名、出版社名、書影、ISBN、あらすじ、販売情報、分類その他本サービス上で表示される書籍に関する情報をいいます。\n5. 「レビュー」とは、登録利用者が、実際に全部又は一部を読んだ書籍について投稿する感想、意見、評価、批評その他の情報をいいます。\n6. 「投稿コンテンツ」とは、登録利用者が本サービス上に投稿、送信、入力又は保存するレビュー、プロフィール、My 本棚、文章その他、運営者が現に提供する投稿機能を通じて保存される情報をいいます。\n7. 「リアクション」とは、「👍」「ハート」「😢」その他運営者が定める方法により、利用者が投稿コンテンツに対して意思表示を行う機能及びその記録をいいます。登録利用者は、同一の投稿に対して同時に一種類のリアクションを付けることができます。\n7-1. 「読みたい！」とは、登録利用者が書籍を今後読みたい作品として保存する機能及び他の登録利用者の投稿を経由して当該意思を表示する機能をいいます。「読みたい！」は前号のリアクションとは別に記録されます。\n8. 「My 本棚」とは、登録利用者が読了レビューを投稿した書籍を、投稿日の新しい順に表示する機能をいいます。\n9. 「返信」とは、登録利用者が、他の登録利用者の投稿又は返信に関連付けて送信する文章をいいます。\n10. 「限定機能」とは、試験提供、個別の利用許可、キャンペーンその他運営者が別途定める条件を満たす登録利用者に限り利用できる機能をいいます。\n11. 「外部サービス」とは、X、Google、Supabase、Vercel、楽天ウェブサービス、楽天アフィリエイト、画像若しくはフォントの配信サービスその他本サービスと連携し、又は本サービスの運営に利用される第三者のサービスをいいます。\n12. 「生成AI」とは、利用者の入力等に基づき、文章、画像、音声、動画その他の情報を自動的に生成又は加工する人工知能を利用したサービス又は機能をいいます。\n13. 「年齢制限対象コンテンツ」とは、性的表現、成人向け表現その他の内容を含み、18歳未満の利用者による閲覧に適さないと運営者が合理的に判断した書籍情報又は投稿コンテンツをいいます。\n\n---\n\n## 第3条（本サービスの内容）\n\n1. 本サービスは、利用者が書籍に関する情報を閲覧し、レビュー及び読書記録を投稿し、My 本棚を作成するとともに、他の利用者と読書体験を共有するための読書レビューSNSです。\n2. 登録利用者は、運営者が提供する範囲で、主に次の機能を利用できます。\n   1) 書籍情報の検索及び閲覧\n   2) 読書記録及びMy 本棚の作成\n   3) レビュー及び評価の投稿\n   4) 文章による感想の投稿\n   5) ネタバレ表示の設定\n   6) アカウント単位の公開・非公開設定\n   7) 他の利用者のフォロー\n   8) 投稿へのリアクション\n   8-1) 書籍又は投稿からの「読みたい！」作品の登録及び一覧表示\n   9) 投稿の通報及び利用者のブロック\n   10) ユーザー名又は公開用のユーザーIDによる登録利用者の検索\n   11) 投稿又は返信に対する返信並びにフォロー、リアクション、「読みたい！」、返信及びフォロー中の登録利用者の新規投稿に関する通知\n   12) その他運営者が現に提供する機能\n3. 本サービス上には、運営者又は第三者が提供する広告、宣伝、商品情報、購入先へのリンクその他の商業的情報が表示されることがあります。\n4. 書籍情報の全部又は一部は、外部サービス又は第三者から提供される場合があります。\n5. 運営者は、本サービスの健全な運営、法令遵守、青少年保護、セキュリティ確保、不正利用防止その他合理的な目的のため、利用者の年齢、利用状況、公開設定その他の条件に応じて、利用できる機能又は表示されるコンテンツを制限することがあります。\n6. 運営者は、必要に応じて本サービスの機能を追加、変更又は廃止することがあります。利用者に重大な影響を及ぼす変更を行う場合は、緊急又はやむを得ない場合を除き、事前に本サービス上への掲載その他適切な方法で周知します。\n\n---\n\n## 第4条（利用料金及び費用）\n\n1. 本サービスは、現時点では無料で提供しており、有料プラン及び定期購入サービスは提供していません。\n2. ページカラーは、青、黄色及び緑を標準色とします。登録利用者は、レビューの投稿件数が10件、25件、50件及び100件に達したとき並びにその後50件増えるごとに、運営者が用意する標準色以外の色から一色を選択して解禁できます。ただし、選択できる色の総数を上限とします。一度解禁した色は、その後レビューを削除して投稿件数が減った場合も利用できます。\n3. 返信、「読みたい！」、お気に入り登録上限の拡張、ページカラーの全色選択その他の一部機能は、試験提供、個別の利用許可、キャンペーンその他運営者が定める条件を満たす登録利用者に限り利用できる限定機能とすることがあります。投稿件数に応じて解禁した色は、限定機能の利用許可が終了した場合も利用できます。\n4. 限定機能の利用許可は、将来にわたる継続利用又は同一条件での提供を保証するものではありません。\n5. 本サービスを利用するために必要な端末、ソフトウェア、インターネット接続環境、通信料金その他の費用は、利用者が負担します。\n6. 運営者は、利用者による明示的な申込み又は同意なく、本サービスについて利用料金を請求しません。\n\n---\n\n## 第5条（利用登録）\n\n1. 本サービスへの利用登録を希望する者は、本規約及びプライバシーポリシーを確認して同意し、運営者が指定する方法により、正確かつ最新の情報を登録しなければなりません。\n2. 運営者は、利用登録に際し、次の情報又は認証を求めることがあります。\n   1) 氏名\n   2) 表示名又はユーザーネーム\n   3) 公開用のユーザーID\n   4) 生年月日\n   5) 電話番号\n   6) Google、X、Facebook、Apple、Discordその他の外部サービスを利用した認証情報\n   7) その他、利用登録、本人確認及び不正利用防止に必要な情報\n3. 利用者は、自らが正当に利用できる電話番号及び外部サービスのアカウントを使用しなければなりません。\n4. 利用登録は、登録申請者について本サービスのアカウントが作成され、運営者所定の登録処理が完了した時点で完了します。\n5. 登録利用者は、登録情報に変更が生じた場合、速やかに運営者所定の方法で当該情報を更新しなければなりません。\n6. 本サービスでは、運営者が別途認めた場合を除き、原則として一人につき一つのアカウントのみを登録できます。\n7. 運営者は、登録申請者が次のいずれかに該当すると合理的に判断した場合、利用登録を承認せず、又は登録後に利用を制限することがあります。\n   1) 登録情報に虚偽、誤記又は重要な記載漏れがある場合\n   2) 他人になりすまし、又は他人の情報を無断で利用した場合\n   3) 過去に利用停止又はアカウント削除の措置を受けた者が再登録しようとした場合\n   4) 複数のアカウントを不正に作成し、又は作成しようとした場合\n   5) 未成年者が必要な法定代理人の同意を得ていない場合\n   6) 本規約又は個別規程に違反する目的で登録しようとした場合\n   7) セキュリティ上又は技術上の危険があると合理的に判断される場合\n   8) その他、本サービスの安全かつ適切な運営に支障がある場合\n8. 運営者は、法令上説明が必要な場合を除き、利用登録を承認しなかった理由の詳細を開示しないことがあります。\n9. 運営者は、利用契約の管理及び同意状況の確認のため、本規約、プライバシーポリシー、コミュニティガイドライン、権利侵害・通報ポリシー及び外部送信に関する公表事項への同意又は確認日時、各文書のバージョンその他必要な情報を記録することがあります。\n10. 公開用のユーザーIDは、他の登録利用者と重複しないものでなければならず、登録完了後、登録利用者自身が変更することはできません。運営者は、なりすまし防止、権利保護、安全管理その他合理的な理由がある場合、特定のユーザーIDの登録を制限し、又は例外的に変更することがあります。\n11. 登録利用者は、運営者所定のアカウント設定からユーザー名を変更できます。\n\n---\n\n## 第6条（未成年者による利用）\n\n1. 未成年者が本サービスの利用登録を行う場合は、あらかじめ親権者その他の法定代理人に、本規約及びプライバシーポリシーの内容を確認してもらい、その同意を得なければなりません。\n2. 未成年者は、登録時に、法定代理人の同意を得ていることを運営者所定の方法で申告するものとします。\n3. 自らの個人情報の取扱いについて、その結果を十分に理解し判断する能力を有しない利用者については、親権者その他の法定代理人が必要な説明を行い、当該利用者に代わって、又は当該利用者とともに同意手続を行うものとします。\n4. 運営者は、未成年者による利用について必要があると合理的に判断した場合、法定代理人の同意を確認するための資料又は連絡を求めることがあります。\n5. 未成年者は、法定代理人の同意を得ていない場合又は法定代理人から利用を中止するよう求められた場合、本サービスを利用してはなりません。\n6. 外部サービスに最低利用年齢その他の利用条件が定められている場合、利用者は当該条件も満たさなければなりません。\n7. 本条は、未成年者について法令上認められる契約の取消しその他の権利を、不当に制限するものではありません。\n\n---\n\n## 第7条（アカウントの管理）\n\n1. 登録利用者は、自己の責任において、アカウント、認証情報、電話番号、外部サービスのログイン情報及び利用端末を適切に管理するものとします。\n2. 登録利用者は、アカウントを第三者に譲渡、貸与、売買若しくは共有し、又は第三者のために利用してはなりません。\n3. 登録利用者のアカウントを使用して行われた行為は、当該登録利用者本人による行為として取り扱われることがあります。ただし、運営者の責めに帰すべき事由による不正利用については、この限りではありません。\n4. 登録利用者は、アカウントの不正利用、認証情報の漏えい又はそのおそれを認識した場合、速やかに認証情報の変更その他必要な措置を講じ、運営者に連絡するものとします。\n5. 登録利用者が外部サービスを利用して本サービスへ登録又はログインする場合、当該外部サービスの利用規約その他の条件にも従うものとします。\n6. 外部サービスのアカウントが停止、削除又は利用不能となった場合、本サービスへのログイン又は一部機能の利用ができなくなることがあります。\n\n---\n\n## 第8条（投稿コンテンツ）\n\n1. 登録利用者は、本規約及び個別規程に従い、レビューその他の文章による投稿コンテンツを投稿できます。レビュー本文は、1件につき1000字以内とします。画像、音声、動画その他の投稿機能を将来提供する場合は、その提供開始時に適用条件を案内します。\n2. 登録利用者は、自ら投稿する投稿コンテンツの内容及び投稿によって生じる結果について責任を負うものとします。\n3. 登録利用者は、投稿コンテンツについて、次の事項を表明し、保証するものとします。\n   1) 自らが投稿するために必要な権利又は適法な許諾を有していること\n   2) 第三者の著作権、著作者人格権、商標権、肖像権、パブリシティ権、名誉、信用、プライバシーその他の権利又は利益を侵害しないこと\n   3) 法令、本規約及び個別規程に違反しないこと\n   4) 投稿に必要な第三者の同意を得ていること\n   5) 虚偽の事実を、真実であるかのように表示しないこと\n4. 登録利用者が、書籍の本文、挿絵、写真、書影その他第三者が権利を有する著作物を投稿コンテンツに含める場合、著作権者等の許諾を得るか、引用その他法令上認められる範囲で利用しなければなりません。\n5. 引用を行う場合、登録利用者は、引用部分と自己の文章を明確に区別し、必要な範囲にとどめ、書名、著者名その他適切な出所を明示するものとします。\n6. 登録利用者は、電子書籍、書籍本文、漫画、挿絵その他の内容を、法令上認められる範囲を超えて撮影、複製又は掲載してはなりません。\n7. 投稿コンテンツは、運営者による事前の審査を経ずに掲載される場合があります。掲載されたことは、運営者が当該投稿コンテンツの適法性、正確性又は妥当性を承認したことを意味しません。\n8. 返信は、対象となる投稿又は返信の文脈に沿って行い、本規約及びコミュニティガイドラインを遵守しなければなりません。返信可能な文字数、階層、表示件数その他の仕様は、運営者が本サービス上で定める範囲によります。\n9. 返信を投稿できる登録利用者は、運営者が定める限定機能の利用条件を満たす者に限られる場合があります。返信の閲覧可否と投稿可否は異なることがあり、返信を閲覧できることは返信を投稿できる権利を意味しません。\n10. 返信は、対象となる投稿の公開範囲及び閲覧権限に従って表示されます。対象投稿の削除、非表示、公開範囲の変更、投稿者若しくは返信者のアカウント状態又はブロック関係等により、返信の全部又は一部が表示されなくなることがあります。\n\n---\n\n## 第9条（レビュー、生成AI及び広告関係の表示）\n\n1. 登録利用者は、実際に全部又は一部を読んだ書籍についてのみレビューを投稿できます。\n2. 書籍の一部のみを読んでレビューを投稿する場合、登録利用者は、可能な限り、そのことが他の利用者に分かるように記載するものとします。\n3. レビューは、登録利用者自身の誠実な感想、意見又は評価に基づいて投稿しなければなりません。\n4. 登録利用者は、書籍を読んでいないにもかかわらず読んだと偽る行為、第三者から指示された評価を自己の評価であるかのように投稿する行為、又は評価を不正に操作する目的でレビューを投稿してはなりません。\n5. 登録利用者が、出版社、著者、販売事業者その他の関係者から、金銭、献本、商品、サービス、割引、招待その他の経済的利益を受けてレビューを投稿する場合又はこれらの者と利害関係を有する場合は、「広告」「PR」「献本」「提供」その他、一般の利用者がその関係を明確に認識できる表示を行わなければなりません。\n6. 登録利用者は、生成AIを利用してレビューその他の投稿コンテンツを作成又は編集できます。ただし、次の事項を遵守しなければなりません。\n   1) 投稿前に内容を自ら確認すること\n   2) 虚偽、誤解を招く情報又は第三者の権利を侵害する内容を投稿しないこと\n   3) 生成AIが作成した内容を、自らの実体験又は読書経験であるかのように偽らないこと\n   4) 自動生成された投稿を大量又は反復して投稿しないこと\n   5) 運営者が合理的な理由により生成AIの利用表示を求めた場合、その表示を行うこと\n7. 生成AIを利用した場合であっても、投稿コンテンツについての責任は、当該投稿を行った登録利用者が負うものとします。\n8. 登録利用者が同一の書籍に対して作成できるレビューは一件とします。登録利用者は、投稿後に感想、評価及びネタバレ設定を編集できますが、対象書籍を変更できません。\n9. 登録利用者がレビューを削除した場合、当該書籍はMy 本棚及びお気に入りからも削除されます。削除後は、同一書籍に再度レビューを投稿できます。\n10. お気に入りに登録できるのは、登録利用者がレビューを投稿した書籍に限られます。通常の登録上限は三冊とし、限定機能の利用条件又は個別の利用許可に応じて、十二冊又は運営者が個別に定める数まで登録できる場合があります。\n11. お気に入りの登録上限が変更された場合であっても、変更前に上限を超えて登録されていた書籍は直ちに削除されません。ただし、登録数が現在の上限以上である間、新たな書籍をお気に入りへ追加できません。\n12. 登録利用者は、書籍詳細又は他の登録利用者の投稿から書籍を「読みたい！」作品へ登録できます。ただし、すでに読了として投稿した書籍は「読みたい！」作品へ登録できません。「読みたい！」作品として登録していた書籍を読了として投稿した場合、当該書籍は「読みたい！」作品から自動的に削除されます。他の登録利用者の投稿を経由して登録した場合、当該投稿には登録数が表示され、投稿者に通知されることがあります。登録利用者は、自らの投稿にリアクション又は「読みたい！」を付けることはできません。\n13. 投稿者は自己の投稿に付いたリアクション又は「読みたい！」を行った登録利用者の一覧を確認できます。他の登録利用者は、運営者所定の長押し、右クリックその他の操作により同じ一覧を確認できる場合があります。\n\n---\n\n## 第10条（投稿コンテンツに関する権利）\n\n1. 投稿コンテンツに関する著作権その他の権利は、登録利用者又は当該権利を有する第三者に留保されます。本規約によって、投稿コンテンツの著作権が運営者へ譲渡されるものではありません。\n2. 登録利用者は、運営者に対し、本サービスの提供、表示、配信、維持、保守、バックアップ、障害対応、セキュリティ確保、不正利用防止、機能改善及び本サービスの紹介に必要な範囲で、投稿コンテンツを無償かつ非独占的に利用することを許諾します。\n3. 前項の許諾には、次の行為が含まれます。\n   1) 本サービス上で投稿コンテンツを複製、公衆送信又は表示すること\n   2) 端末又は表示形式に合わせて、文字コードの変換、改行調整その他技術上必要な処理を行うこと\n   3) キャッシュ、バックアップ及び障害復旧用データを作成すること\n   4) 本サービスの提供に必要な範囲で、業務委託先又は外部サービス提供事業者に取り扱わせること\n   5) 公開された投稿コンテンツの一部を、本サービスの公式アカウント又は本サービスを紹介する画面等に掲載すること\n4. 運営者は、登録利用者の個別の同意を得ることなく、投稿コンテンツの趣旨を実質的に変更する編集を行い、又は投稿コンテンツを本サービスと無関係な商品若しくはサービスの宣伝に利用しません。\n5. 運営者が、利用者を容易に特定できる状態で、投稿コンテンツの主要部分を本サービス外の広告等に使用する場合は、法令上不要とされる場合を除き、当該利用者の同意を得るものとします。\n6. 登録利用者は、第2項及び第3項に定める技術上又は運営上必要な利用の範囲に限り、運営者及び運営者から正当に権利を承継し、又は利用を委託された者に対して、著作者人格権を行使しないものとします。\n7. 投稿コンテンツが削除された場合、第2項の利用許諾は原則として終了します。ただし、次の場合は、必要な範囲で引き続き取り扱われることがあります。\n   1) 他の利用者によるリアクションその他関連する記録の整合性維持に必要な場合\n   2) バックアップ又はログから削除されるまでの合理的な期間\n   3) 法令遵守、紛争対応、不正利用調査又は権利保護のため保存が必要な場合\n   4) 統計化又は匿名化され、特定の利用者と結び付かない情報となっている場合\n\n---\n\n## 第11条（公開範囲及びネタバレ）\n\n1. 登録利用者は、アカウント単位で公開又は非公開（鍵アカウント）を設定できます。投稿ごと又はMy 本棚ごとの公開範囲設定は、現時点では提供していません。\n2. 公開アカウントの投稿コンテンツは、登録していない者を含む第三者に閲覧され、検索エンジンの検索結果に表示され、又は第三者によって共有される場合があります。\n3. 鍵アカウントの設定は、本サービス上における表示範囲を制御するものであり、秘密保持契約その他の法的な秘密保持を保証するものではありません。\n4. 運営者及び運営者の業務委託先は、本サービスの提供、障害対応、不正利用調査、通報対応、法令遵守その他正当な目的に必要な範囲で、鍵アカウントの投稿コンテンツを取り扱うことがあります。\n5. 鍵アカウントに設定された登録利用者をフォローするには、当該登録利用者へフォローリクエストを送り、その承認を得る必要があります。承認されるまで、当該鍵アカウントの投稿、My 本棚、お気に入り及び「読みたい！」作品は閲覧できません。\n6. 鍵アカウントの登録利用者は、フォローリクエストを承認又は拒否し、承認後も相手をブロックできます。鍵アカウントとのフォロー関係が解除された後は、その投稿、My 本棚、お気に入り及び「読みたい！」作品の閲覧が制限されます。また、ブロックされた利用者による投稿等の閲覧、フォロー、リアクション及び「読みたい！」は制限されます。ただし、ログアウト状態、別アカウント、検索エンジン又は第三者による共有を通じた公開情報の閲覧を完全に防止するものではありません。\n7. 公開アカウントのフォロー及びフォロワーの一覧は、他の登録利用者に表示されます。鍵アカウントの当該一覧は、当該アカウント本人にのみ表示されます。\n8. 登録利用者は、物語の結末、犯人、重要人物の生死、重大な展開その他、書籍を読む楽しみを大きく損なうおそれのある情報を投稿又は返信する場合、運営者が提供するネタバレ表示機能を使用しなければなりません。\n9. ネタバレ表示が設定された投稿又は返信の本文は、閲覧者が表示操作を行うまで隠され、再表示時には再び隠れることがあります。\n10. 運営者は、投稿コンテンツがネタバレを含むと合理的に判断した場合、投稿者への事前の通知なく、ネタバレ表示の追加又は表示方法の変更を行うことがあります。\n\n---\n\n## 第12条（年齢制限対象コンテンツ）\n\n1. 運営者は、18歳未満の利用者を保護するため、年齢制限対象コンテンツについて、次の措置を講じることがあります。\n   1) 検索結果、一覧その他の表示領域に表示しないこと\n   2) 書籍情報又は投稿コンテンツを非表示にすること\n   3) 閲覧前に警告を表示すること\n   4) 一部の画像、文章、音声又は動画を隠すこと\n   5) 投稿、閲覧又はリアクション等の機能を制限すること\n   6) その他青少年保護のために必要な措置\n2. 年齢制限対象コンテンツに該当するかどうかは、書籍情報、題名、説明、画像、投稿内容、外部から提供される情報、利用者からの通報その他の事情を考慮し、運営者所定の基準に基づいて判断します。\n3. 年齢制限の判定方法及び基準の詳細は、表示制限の回避、不正利用その他本サービスの安全な運営を妨げるおそれがある場合、公開しないことがあります。\n4. 登録利用者は、正確な生年月日を登録しなければならず、年齢制限を回避する目的で虚偽の生年月日を登録してはなりません。\n5. 利用者は、伏字、記号、異体字、画像、隠語その他の方法により、年齢制限又は表示制限を意図的に回避してはなりません。\n6. 運営者は、年齢制限対象コンテンツの適切な表示制限のため合理的な措置を講じますが、書籍情報又は投稿コンテンツの性質上、すべての対象コンテンツを事前かつ完全に判定できることを保証するものではありません。\n7. 18歳未満の利用者に年齢制限対象コンテンツが表示された場合、利用者又は法定代理人は、通報機能又は運営者所定の窓口から運営者へ連絡できます。運営者は、連絡を受けた場合、合理的な期間内に内容を確認し、必要に応じて表示制限、修正、削除その他の措置を講じます。\n8. 書籍が成人向けであることは、違法なコンテンツ、わいせつな画像若しくは動画、児童の性的搾取に関するコンテンツ又は第三者の権利を侵害するコンテンツの投稿を許容するものではありません。\n9. 年齢制限対象コンテンツの投稿及び取扱いについては、本規約のほか、コミュニティガイドラインが適用されます。\n\n---\n\n## 第13条（禁止事項）\n\n利用者は、本サービスの利用に際し、自ら又は第三者を通じて、次の各号に掲げる行為を行ってはなりません。\n1. 法令、裁判所の判決、決定若しくは命令又は法令上拘束力のある行政措置に違反する行為\n2. 犯罪行為に関連する行為、犯罪を助長する行為又は犯罪の予告を行う行為\n3. 詐欺、脅迫、恐喝、違法な勧誘その他第三者に損害を与える行為\n4. 公序良俗に反する行為\n5. 第三者の著作権、著作者人格権、商標権、特許権、肖像権、パブリシティ権その他の知的財産権を侵害し、又は侵害するおそれのある行為\n6. 第三者の名誉、信用、プライバシー、個人情報その他の権利又は利益を侵害する行為\n7. 第三者を不当に差別し、誹謗中傷し、侮辱し、威迫し、嫌がらせをし、又はこれらを助長する行為\n8. 人種、国籍、民族、出身地、信条、性別、性的指向、性自認、障害、疾病、職業その他の属性を理由とする不当な差別又は差別の助長に当たる行為\n9. 第三者の氏名、住所、電話番号、メールアドレス、勤務先、学校名、位置情報、顔写真その他個人を特定し得る情報を、本人の同意なく公開する行為\n10. 他の利用者、著者、出版社、書店、運営者その他の第三者に成りすます行為\n11. 他人のアカウントを利用する行為又は自己のアカウントを第三者に利用させる行為\n12. 虚偽又は誤解を招く情報を故意に投稿し、又は拡散する行為\n13. 書籍を読んでいないにもかかわらず、読んだものとしてレビューを投稿する行為\n14. 出版社、著者、販売事業者その他の第三者から受けた依頼、指示又は経済的利益を適切に表示せず、広告又は宣伝であることを隠してレビューその他の投稿を行う行為\n15. 金銭、物品、ポイント、相互評価その他の利益を提供し、又は受けることにより、レビュー、評価、フォロー又はリアクションを不正に増減させる行為\n16. 複数のアカウント、ボット、自動操作、第三者への依頼その他不正な手段を用いて、レビュー、評価、閲覧数、フォロー数又はリアクション数を操作する行為\n17. 特定の書籍、著者、出版社、利用者その他の対象について、組織的に不当な高評価若しくは低評価を行い、又はそのような行為を呼びかける行為\n18. 同一又は類似する内容を大量又は反復して投稿する行為\n19. 宣伝、勧誘、アフィリエイト、紹介報酬の獲得その他営利を主な目的とする投稿を、運営者が認めていない方法で行う行為\n20. 連鎖販売取引、無限連鎖講、悪質な情報商材、違法な金融取引その他不適切な商品又はサービスを勧誘する行為\n21. わいせつな情報、違法な性的コンテンツ、児童の性的搾取若しくは虐待に関する情報又はこれらを助長する情報を投稿、送信又は保存する行為\n22. 自殺、自傷行為、薬物乱用その他生命又は身体に重大な危険を生じさせる行為を具体的に推奨し、教唆し、又は助長する行為\n23. 年齢制限対象コンテンツに関する表示制限を、伏字、記号、異体字、隠語、画像、音声、虚偽の書籍情報その他の方法により意図的に回避する行為\n24. 虚偽の生年月日を登録し、又は他人の年齢情報を利用することにより、年齢制限を回避する行為\n25. ネタバレ表示機能を意図的に回避し、他の利用者の読書体験を著しく害する目的で投稿する行為\n26. マルウェア、コンピューターウイルスその他有害なプログラムを送信し、又はこれらを含むリンクを掲載する行為\n27. 本サービスのサーバー、ネットワーク、データベースその他のシステムに不正にアクセスし、又は不正アクセスを試みる行為\n28. 本サービスの脆弱性を探索し、セキュリティ機能、認証機能、アクセス制御その他の技術的制限を回避し、又は無効化する行為\n29. 本サービスに過度な負荷を与え、又は正常な運営を妨害する行為\n30. 運営者の事前の許可なく、クローリング、スクレイピング、ボットその他の自動的手段を用いて、本サービス上の情報を大量に取得、複製又は収集する行為\n31. 運営者の事前の許可なく、本サービス又は本サービス上のデータを、データセットの作成、機械学習若しくは生成AIの学習又はこれらに類する目的で大量に利用する行為\n32. 本サービスの全部又は一部について、リバースエンジニアリング、逆コンパイル、逆アセンブル、ソースコード又は内部構造の解析を行う行為。ただし、法令により明示的に認められる場合を除きます。\n33. 本サービスの不具合又は仕様上の問題を、自己若しくは第三者の利益又は本サービスへの損害のために悪用する行為\n34. 通報、異議申立て、問い合わせその他の制度を、嫌がらせ、報復、業務妨害又は虚偽申告の目的で利用する行為\n35. 運営者、他の利用者又は第三者による本サービスの利用若しくは運営を妨害する行為\n36. 前各号の行為を援助、教唆、勧誘又は準備する行為\n37. その他、本規約又は個別規程に違反し、本サービスの安全、公平性又は健全な運営を著しく害すると合理的に認められる行為\n\n---\n\n## 第14条（投稿コンテンツ等に対する措置）\n\n1. 運営者は、投稿コンテンツ又は利用行為が、本規約若しくは個別規程に違反し、法令に違反し、第三者の権利を侵害し、又は本サービスの安全若しくは健全な運営を害すると合理的に判断した場合、必要かつ相当な範囲で、次の措置を講じることがあります。\n   1) 注意又は警告\n   2) 投稿コンテンツの表示制限\n   3) ネタバレ表示又は警告表示の追加\n   4) 年齢制限の設定又は変更\n   5) 検索結果その他の表示領域への表示の制限\n   6) 投稿コンテンツの一部又は全部の非表示\n   7) 投稿コンテンツの削除\n   8) リアクション、フォロー、投稿その他の機能の制限\n   9) アカウントの一時停止又は削除\n   10) その他、違反又は被害を防止するために必要な措置\n2. 運営者は、措置を決定するに当たり、投稿内容、投稿の文脈、違反の程度、故意性、反復性、被害の内容、利用者の過去の利用状況その他の事情を考慮するよう努めます。\n3. 批判的、否定的又は低評価のレビューであることのみを理由として、当該レビューを本規約違反として取り扱うものではありません。書籍、著者、出版社その他に対する正当な批評又は意見は、本規約及び法令に違反しない限り認められます。\n4. 運営者は、投稿コンテンツの検出、分類又は確認を補助するため、自動的又は機械的な判定を利用することがあります。\n5. 緊急性が高い場合、被害の拡大を防止する必要がある場合、セキュリティ上の危険がある場合又は法令若しくは公的機関からの要請に対応する場合、運営者は、利用者への事前通知なく措置を講じることがあります。\n6. 運営者は、措置を講じた場合、原則として、対象となった登録利用者に対し、措置の内容及び主な理由を通知します。ただし、次のいずれかに該当する場合は、その全部又は一部を通知しないことがあります。\n   1) 通知により第三者の権利又は安全が害されるおそれがある場合\n   2) 不正利用、セキュリティ上の問題又は違反行為の調査を妨げるおそれがある場合\n   3) 通報者その他第三者の特定につながるおそれがある場合\n   4) 法令、裁判所、捜査機関その他公的機関から通知を制限されている場合\n   5) 違反が軽微であり、表示方法の修正等によって対応した場合\n   6) その他、通知しないことに合理的な理由がある場合\n7. 運営者は、本サービス上のすべての投稿コンテンツを常時監視し、又は事前に審査する義務を負うものではありません。\n8. 運営者による措置は、投稿コンテンツ又は利用行為の適法性、違法性、権利侵害の有無その他の法的判断を確定するものではありません。\n9. 運営者は、違反調査、通報対応、法令遵守、紛争対応又は証拠保全に必要な範囲で、削除又は非表示とした投稿コンテンツ、操作記録その他の情報を一定期間保存することがあります。\n\n---\n\n## 第15条（通報）\n\n1. 利用者は、本規約若しくは個別規程に違反するおそれのある投稿コンテンツ又は利用行為を発見した場合、本サービス上の通報機能又は運営者が指定する窓口から通報できます。\n2. 通報者は、可能な範囲で次の情報を提供するものとします。\n   1) 対象となる投稿コンテンツ、アカウント又はページ\n   2) 通報理由\n   3) 問題となる具体的な箇所\n   4) 関係する権利又は事情\n   5) その他運営者が確認のために必要とする情報\n3. 運営者は、通報内容の確認に必要な場合、通報者に追加の説明、資料又は本人確認を求めることがあります。\n4. 運営者は、通報内容、対象となる投稿コンテンツ、当事者から提供された情報その他の事情を確認し、必要に応じて第14条に定める措置を講じます。\n5. 通報が行われたことのみを理由として、対象となる投稿コンテンツの削除又はアカウントの停止が行われるものではありません。\n6. 運営者は、通報に対する判断結果について、合理的な範囲で通報者へ通知することがあります。ただし、対象利用者又は第三者の個人情報、調査方法、セキュリティ情報その他開示することが適切でない情報は通知しないことがあります。\n7. 通報者の情報は、法令に基づく場合、通報への対応に必要な場合又は通報者本人の同意がある場合を除き、対象利用者に開示しません。\n8. 利用者は、虚偽であることを知りながら通報し、他の利用者に対する嫌がらせ若しくは報復のために通報し、又は同一内容の通報を合理的な理由なく繰り返してはなりません。\n\n---\n\n## 第16条（権利侵害に関する申出）\n\n1. 自己の著作権、商標権、肖像権、名誉、プライバシーその他の権利又は利益が、本サービス上の投稿コンテンツによって侵害されていると考える者は、権利侵害・通報ポリシーに従い、運営者へ削除その他の対応を申し出ることができます。\n2. 前項の申出を行う者は、原則として、次の情報を提供するものとします。\n   1) 申出者の氏名又は名称及び連絡先\n   2) 対象となる投稿コンテンツを特定する情報\n   3) 侵害されたとする権利の内容\n   4) 権利侵害であると考える具体的な理由\n   5) 申出者が当該権利を有し、又は権利者を代理することを示す資料\n   6) 希望する対応\n   7) その他運営者が確認に必要とする情報\n3. 運営者は、申出の真正性又は内容を確認するため、本人確認書類、委任状、権利を証明する資料その他必要な情報の提出を求めることがあります。\n4. 運営者は、法令上又は事実確認上必要である場合、申出内容の全部又は一部を、対象となる投稿コンテンツを投稿した利用者に通知し、意見又は資料の提出を求めることがあります。\n5. 運営者は、申出内容、投稿者から提出された意見及び資料、投稿の文脈、公益性その他の事情を考慮し、必要に応じて、表示制限、削除その他の措置を講じます。\n6. 運営者は、権利侵害の有無について裁判所と同等の法的判断を行う立場にはなく、判断が困難な場合には、裁判所の手続その他適切な法的手段の利用を案内することがあります。\n7. 運営者は、法令、裁判所の命令その他適法な手続に基づき、投稿者に関する情報の保存又は開示を求められた場合、当該手続に従って対応します。\n\n---\n\n## 第17条（異議申立て）\n\n1. 投稿コンテンツの非表示若しくは削除、機能制限、アカウント停止その他の措置を受けた登録利用者は、運営者が指定する方法及び期間内に、当該措置について異議を申し立てることができます。\n2. 異議申立てを行う登録利用者は、次の情報を提供するものとします。\n   1) 対象となる措置\n   2) 異議を申し立てる理由\n   3) 判断に誤りがあると考える具体的な事情\n   4) 判断に必要となる資料\n   5) その他運営者が指定する情報\n3. 運営者は、提出された情報を確認し、必要に応じて、措置を維持、変更又は取り消します。\n4. 運営者は、可能な範囲で、当初の判断に直接関与していない者による確認その他、公平性に配慮した方法で異議申立てを検討するよう努めます。\n5. 運営者は、異議申立ての結果を、合理的な範囲で申立者に通知します。\n6. 同一の措置について、既に十分な検討が行われ、新たな事実又は資料が提示されていない場合、運営者は、繰り返し行われる異議申立てを受け付けないことがあります。\n7. 異議申立てを行ったことのみを理由として、登録利用者を不利益に取り扱うことはありません。ただし、異議申立て制度を嫌がらせ、虚偽申告又は業務妨害の目的で利用した場合は、この限りではありません。\n\n---\n\n## 第18条（ブロックその他の利用者保護機能）\n\n1. 登録利用者は、運営者が提供する範囲で、特定の利用者をブロックし、又はその投稿コンテンツを非表示にできます。\n2. ブロックにより制限される機能及び表示範囲は、運営者が定める仕様によります。\n3. ブロックされた利用者が、ログアウト状態、別のアカウント、検索エンジン、共有された情報その他の方法により、公開された投稿コンテンツを閲覧できる場合があります。\n4. ブロック機能は、利用者間の接触又は閲覧を完全に防止することを保証するものではありません。\n5. 利用者は、ブロックを回避する目的で別のアカウントを作成し、第三者のアカウントを利用し、又は他の手段により相手方へ接触してはなりません。\n6. 脅迫、つきまとい、個人情報の公開その他緊急性のある被害が生じている場合、利用者は、必要に応じて警察、弁護士その他適切な機関へ相談するものとします。\n\n---\n\n## 第19条（利用制限、利用停止及びアカウント削除）\n\n1. 運営者は、登録利用者が次のいずれかに該当すると合理的に判断した場合、事前の通知又は催告を行った上で、当該登録利用者による本サービスの利用を制限若しくは停止し、又はアカウントを削除できます。\n   1) 本規約又は個別規程に違反した場合\n   2) 登録情報に重要な虚偽がある場合\n   3) 第三者になりすました場合\n   4) 不正な方法で複数のアカウントを作成又は利用した場合\n   5) 本サービスの運営又はセキュリティに重大な支障を及ぼした場合\n   6) 運営者からの合理的な確認又は是正の要請に応じない場合\n   7) 法令又は公的機関からの要請に基づき対応する必要がある場合\n   8) その他、本サービスの利用を継続させることが著しく不適切である場合\n2. 次のいずれかに該当する場合、運営者は、事前の通知又は催告を行わずに措置を講じることがあります。\n   1) 第三者の生命、身体、財産又は権利に対する差し迫った危険がある場合\n   2) 犯罪、不正アクセス、重大な権利侵害又は深刻な嫌がらせが疑われる場合\n   3) 証拠の隠滅、被害の拡大又は措置の回避を防止する必要がある場合\n   4) セキュリティ上緊急の対応が必要な場合\n   5) 法令、裁判所又は公的機関から直ちに対応することを求められた場合\n3. 運営者は、違反の内容及び程度に応じ、警告、投稿制限、一時停止その他、アカウント削除より軽い措置を選択するよう努めます。ただし、重大又は反復的な違反については、この限りではありません。\n4. 運営者は、利用停止の措置を講じた場合又はアカウント削除前に連絡手段を利用できる場合、原則として、その内容及び主な理由を登録利用者に通知します。ただし、第14条第6項各号に該当する場合又は削除により連絡先を利用できない場合は、その全部又は一部を通知しないことがあります。\n5. 利用停止又はアカウント削除を受けた者は、運営者の許可なく、別の電話番号、外部サービスのアカウント、第三者の情報その他の方法を利用して再登録してはなりません。\n6. 運営者による利用停止又はアカウント削除後も、登録利用者が本規約に基づいて負担する債務及び責任は消滅しません。\n7. 運営者は、管理者によるアカウント削除を受けた者による不正な再登録を防止するため、プライバシーポリシーに定める範囲及び期間において、氏名及び生年月日と、メールアドレス又は電話番号との組み合わせから作成した復元できない照合値を保存し、新たな利用登録時に照合することがあります。\n\n---\n\n## 第20条（退会及び退会後のデータ）\n\n1. 登録利用者は、運営者が指定する方法により、いつでも本サービスから退会できます。\n2. 退会手続が完了した場合、登録利用者は、本サービス上のアカウント及び当該アカウントに紐づく機能を利用できなくなります。\n3. 運営者は、退会した登録利用者のアカウント情報、個人情報及び投稿コンテンツについて、第6項及び第7項に定める場合を除き、退会手続の完了日から90日以内に削除し、又は特定の個人との対応関係を復元できない方法により匿名化します。\n4. 運営者は、退会処理の確認、問い合わせ対応、不正利用若しくはセキュリティ上の問題の調査、紛争対応又は裁判所、警察その他の公的機関からの適法な照会への対応のため、元の利用者識別子、ユーザー名、公開用のユーザーID、氏名、生年月日、メールアドレス、電話番号、認証方式、退会種別、退会日時、削除処理の成否、削除実行者及び必要最小限の対応履歴を、退会手続又は削除処理から90日を上限として非公開で保存することがあります。\n5. 運営者は、退会後の情報を、次の目的に必要な範囲で、退会手続の完了日から90日を上限として一時的に保存することがあります。\n   1) アカウント及び関連データの削除処理\n   2) 利用者からの問い合わせへの対応\n   3) 退会手続に関する確認\n   4) 不正利用、権利侵害又はセキュリティ上の問題の調査\n   5) 苦情、紛争又は法的請求への対応\n   6) バックアップ及び障害復旧に伴う技術的な処理\n6. 次の情報については、前3項にかかわらず、それぞれの目的に必要な期間保存することがあります。\n   1) 法令により保存が義務付けられている情報\n   2) 訴訟、紛争、通報、権利侵害又は不正利用への対応に必要な情報\n   3) 捜査機関、裁判所その他の公的機関から、適法に保存又は提供を求められた情報\n   4) 情報漏えい、不正アクセスその他のセキュリティ上の事故の調査に必要な情報\n   5) バックアップ媒体から直ちに削除することが技術上困難であり、通常の運用では利用されない状態で保存される情報\n   6) 統計化又は匿名化され、特定の利用者を識別できない情報\n7. 裁判所、警察その他の公的機関から適法な保存要請若しくは照会を受けた場合、又は具体的な紛争、通報、権利侵害若しくは不正利用への対応に必要な場合、運営者は、対象となる退会記録に法的保存措置を設定し、前3項の期間を超えて必要な期間保存することがあります。保存の必要がなくなった場合、当該措置を解除し、合理的な期間内に削除又は匿名化します。\n8. 前2項に基づいて情報を保存する場合、運営者は、当該保存目的に必要な範囲を超えて利用せず、保存する必要がなくなった後、合理的な期間内に削除又は匿名化します。\n9. 他の利用者による返信、引用又は共有の対象となった投稿コンテンツについては、会話その他の表示を維持するため、投稿者を特定しにくい状態に変更した上で残る場合があります。\n10. 退会前に利用者自身が外部へ共有し、又は第三者が保存若しくは転載した情報について、運営者は、当該第三者に対して削除を強制できない場合があります。\n11. 退会後に一時的に保存されているデータは、削除処理、法令対応その他本条に定める目的のために保存されるものであり、運営者は、利用者によるデータの閲覧、復元又は提供を保証しません。\n12. 第8条、第10条、第13条、第14条第9項、本条その他その性質上退会後も存続すべき規定は、退会後も有効に存続します。\n\n---\n\n## 第21条（本サービスに関する知的財産権）\n\n1. 本サービスを構成するプログラム、デザイン、ロゴ、画面構成、文章その他運営者が提供するコンテンツに関する知的財産権は、運営者又は正当な権利者に帰属します。\n2. 書籍情報、書影、表紙画像その他第三者が権利を有するコンテンツに関する知的財産権は、それぞれの権利者に帰属します。\n3. 利用者は、法令で認められる場合を除き、運営者又は権利者の許可なく、本サービス上のコンテンツを複製、転載、配布、公衆送信、販売その他の方法で利用してはなりません。\n4. 本サービス上に表示される書影、書籍の説明、著者名、出版社名その他第三者から提供された情報に関する権利は、当該情報の提供者又は権利者に帰属します。\n\n---\n\n## 第22条（書籍情報及び外部サービス）\n\n1. 本サービス上に表示される書籍情報の全部又は一部は、外部サービスから取得し、又は第三者から提供を受ける場合があります。\n2. 書籍情報は、外部サービスの仕様、登録内容、通信状況その他の事情により、次の状態となる場合があります。\n   1) 情報が不正確又は不完全であること\n   2) 表示されないこと\n   3) 更新が遅れること\n   4) 重複又は誤った情報が表示されること\n   5) 書影その他の情報が変更又は削除されること\n3. 利用者は、購入、引用、研究その他重要な目的で書籍情報を利用する場合、出版社、著者、販売事業者その他の正式な情報源を自ら確認するものとします。\n4. 本サービスは現在、X及びGoogleを利用した認証機能を提供しています。その他の外部サービスによる認証は、設定完了後に提供する場合があります。\n5. 外部サービスの利用については、当該外部サービスの利用規約、プライバシーポリシーその他の条件に従うものとします。\n6. 本サービスは、書籍詳細に楽天アフィリエイトによる楽天ブックスへのリンクを表示することがあります。利用者が当該リンクを選択した後の購入契約、配送、返品、支払その他の商品取引は楽天グループ株式会社又は当該販売者と利用者との間で行われ、運営者は当該取引の当事者となりません。\n\n---\n\n## 第23条（広告及び外部サイト）\n\n1. 本サービスには、運営者又は第三者が提供する広告、宣伝、商品情報、書籍販売ページへのリンクその他の商業的情報が表示されることがあります。\n2. 広告の内容、表示場所、表示方法及び配信頻度は、運営者又は広告配信事業者が定めます。\n3. 利用者の端末から広告配信事業者その他の外部事業者へ送信される情報及びその利用目的については、プライバシーポリシー及び外部送信に関する公表事項に定めます。\n4. 本サービス上の広告又はリンクを通じて、利用者が広告主、販売事業者その他の第三者の商品又はサービスを利用する場合、その契約は、当該利用者と第三者との間で成立します。\n5. 運営者自身が商品又はサービスの販売者若しくは提供者として明示されている場合を除き、運営者は、前項の契約の当事者とはなりません。\n6. 利用者は、商品又はサービスの購入前に、価格、送料、返品条件、利用条件、販売者情報その他必要な事項を自ら確認するものとします。\n7. 広告又はリンクが本サービス上に掲載されていることは、運営者が当該商品、サービス、広告主又は外部サイトの内容、安全性、合法性若しくは品質を保証又は推奨することを意味しません。ただし、運営者が明示的に推奨している場合を除きます。\n8. 運営者は、違法若しくは不適切な広告又は利用者に重大な不利益を与えるおそれのある広告を認識した場合、合理的な範囲で、その掲載停止、広告配信事業者への連絡その他必要な対応を行うよう努めます。\n\n---\n\n## 第24条（利用環境及び通信費）\n\n1. 利用者は、本サービスを利用するために必要な端末、ソフトウェア、インターネット接続環境その他の設備を、自己の責任と費用において準備し、維持するものとします。\n2. 本サービスの利用に伴う通信料、インターネット接続料その他の費用は、利用者が負担します。\n3. 運営者は、すべての端末、OS、ブラウザ、通信環境その他の利用環境において、本サービスが同一の状態で動作することを保証するものではありません。\n4. 運営者は、安全性又は正常な動作を確保するため、推奨する利用環境を指定し、又は旧式の端末、OS若しくはブラウザ等に対する対応を終了することがあります。\n5. 運営者は、利用環境への対応を終了する場合、可能な範囲で事前に周知します。ただし、重大なセキュリティ上の危険がある場合その他緊急の対応が必要な場合は、この限りではありません。\n\n---\n\n## 第25条（本サービスの停止、中断及び終了）\n\n1. 運営者は、次のいずれかに該当する場合、本サービスの全部又は一部を一時的に停止又は中断することがあります。\n   1) システム、サーバー、ネットワークその他の設備について、保守、点検、修理又は更新を行う場合\n   2) 本サービスへのアクセスが集中し、正常な提供が困難となった場合\n   3) 不正アクセス、サイバー攻撃、マルウェア、情報漏えいその他のセキュリティ上の問題が発生し、又はそのおそれがある場合\n   4) 外部サービス、通信事業者、クラウドサービスその他第三者のサービスに障害又は提供停止が生じた場合\n   5) 地震、台風、洪水、火災、停電、感染症、戦争、暴動、テロ、労働争議その他の不可抗力が生じた場合\n   6) 法令、裁判所、行政機関その他の公的機関から対応を求められた場合\n   7) その他、本サービスの安全又は継続的な提供のため、停止又は中断が必要であると合理的に判断した場合\n2. 運営者は、予定された保守その他事前に周知することが可能な停止又は中断について、合理的な期間を設けて、本サービス上への掲載その他適切な方法により周知するよう努めます。\n3. 緊急の保守、セキュリティ対応、不可抗力その他事前の周知が困難な場合、運営者は、事前の周知を行わずに本サービスを停止又は中断することがあります。この場合、運営者は、可能となった時点で状況を周知するよう努めます。\n4. 運営者は、次のいずれかに該当する場合、本サービスの全部又は重要な一部を終了することがあります。\n   1) 本サービスの継続が事業上又は経済上困難となった場合\n   2) 本サービスの継続に必要なシステム、外部サービス又は取引関係を維持できなくなった場合\n   3) 法令、行政上の要請又は社会情勢の変化により、本サービスの継続が困難となった場合\n   4) セキュリティ上の重大な危険があり、その解消が困難である場合\n   5) 災害その他の不可抗力により、本サービスの復旧又は継続が困難となった場合\n   6) その他、本サービスを終了することについて合理的な理由がある場合\n5. 運営者が本サービスの全部又は重要な一部を終了する場合、緊急又はやむを得ない場合を除き、原則として終了日の30日前までに、終了日、終了する機能、利用者が行うべき手続その他必要な事項を、本サービス上への掲載その他適切な方法により周知します。\n6. 運営者は、本サービスを終了する場合、技術上及び運営上可能な範囲で、終了日までの間に、登録利用者が自己のレビュー、My 本棚、読書記録その他の投稿コンテンツを確認又は保存するための方法若しくは期間を設けるよう努めます。\n7. 本サービスの終了後、利用者は、アカウント、投稿コンテンツ、My 本棚、読書記録その他本サービス上のデータを閲覧、編集又は取得できなくなる場合があります。利用者は、必要な情報について、本サービスの終了日までに自ら保存するものとします。\n8. 運営者は、本サービスの終了後、利用者に関する情報及び投稿コンテンツを、次の目的に必要な範囲で一時的に保存することがあります。\n   1) データの削除、移行及びシステムの終了処理\n   2) 利用者からの問い合わせへの対応\n   3) 不正利用、権利侵害又はセキュリティ上の問題の調査\n   4) 紛争、苦情又は法的請求への対応\n   5) 法令、裁判所又は公的機関からの要請への対応\n   6) バックアップ及び障害復旧に伴う技術的な処理\n9. 運営者は、前項に基づき保存する情報について、第10項に定める場合を除き、本サービスの終了日から3か月以内に削除し、又は特定の個人との対応関係を復元できない方法により匿名化します。\n10. 次の情報については、前項にかかわらず、それぞれの目的に必要な期間保存することがあります。\n    1) 法令により保存が義務付けられている情報\n    2) 訴訟、紛争、通報、権利侵害又は不正利用への対応に必要な情報\n    3) 捜査機関、裁判所その他の公的機関から、適法に保存又は提供を求められた情報\n    4) セキュリティ上の事故又は不正アクセスの調査に必要な情報\n    5) バックアップ媒体から直ちに削除することが技術上困難であり、通常の運用では利用されない状態で保存される情報\n    6) 統計化又は匿名化され、特定の利用者を識別できない情報\n11. 前項の例外に基づいて情報を保存する場合、運営者は、当該保存目的に必要な範囲を超えて利用せず、保存する必要がなくなった後、合理的な期間内に削除又は匿名化します。\n12. 本サービスの終了後に一時的に保存されているデータは、削除処理、法令対応その他本条に定める目的のためのものであり、運営者は、利用者によるデータの閲覧、復元又は提供を保証しません。\n13. 本サービスの終了は、終了前に発生した利用者又は運営者の権利、義務及び責任に影響を与えません。また、その性質上、本サービスの終了後も存続すべき規定は、終了後も有効に存続します。\n\n---\n\n## 第26条（非保証）\n\n1. 運営者は、本サービスの安全かつ安定的な運営のため、合理的な措置を講じるよう努めます。\n2. 本サービスは、現状有姿で、運営者が提供可能な範囲において提供されます。\n3. 運営者は、次の事項について、明示又は黙示を問わず、完全に保証するものではありません。\n   1) 本サービスが常時中断なく利用できること\n   2) 本サービスに不具合、エラー又はセキュリティ上の問題が一切存在しないこと\n   3) 本サービス上の情報が常に正確、完全、最新又は有用であること\n   4) 書籍情報、検索結果その他の表示が、利用者の目的又は期待に合致すること\n   5) 投稿コンテンツが事前に審査され、又は本規約に違反する投稿コンテンツが一切表示されないこと\n   6) 年齢制限対象コンテンツ又はネタバレを含むコンテンツが、完全に検出又は非表示となること\n   7) 投稿コンテンツ, アカウント情報その他のデータが、いかなる場合にも消失又は破損しないこと\n   8) 外部サービスが継続的かつ正常に提供されること\n   9) 他の利用者の身元、年齢、経歴、投稿内容又は行動が真実又は適切であること\n4. 前項は、運営者が本規約、プライバシーポリシー又は法令に基づいて負うべき義務を免除するものではありません。\n5. 利用者は、本サービス上の情報を、医療、法律、金融、投資その他専門的判断の代替として利用せず、必要に応じて専門家又は公的機関へ相談するものとします。\n\n---\n\n## 第27条（運営者の責任）\n\n1. 運営者は、運営者の責めに帰すべき事由により利用者に損害を生じさせた場合、適用される法令に従い、当該損害を賠償します。\n2. 運営者の故意又は重大な過失によって利用者に損害が生じた場合、運営者は、本規約に定める責任制限を適用しません。\n3. 運営者の軽過失によって利用者に損害が生じた場合、法令により許容される範囲において、運営者が負う損害賠償責任の範囲は、当該事由から通常生ずべき、現実かつ直接の損害に限られるものとします。\n4. 前項は、消費者契約法その他の強行法規により、当該責任の制限が認められない場合には適用されません。\n5. 次の事由によって損害が発生した場合であっても、当該損害について運営者の責めに帰すべき事由があるときは、前各項に従って運営者の責任を判断します。\n   1) 本サービスの停止、中断、変更又は終了\n   2) 投稿コンテンツの非表示又は削除\n   3) 利用制限、利用停止又はアカウント削除\n   4) データの消失、破損又は表示上の不具合\n   5) 外部サービス又は広告に関連する問題\n   6) 年齢制限対象コンテンツ、ネタバレその他不適切なコンテンツの表示\n6. 運営者は、利用者間又は利用者と第三者との間の紛争について、当然に当事者となるものではありません。ただし、当該紛争について運営者の責めに帰すべき事由がある場合又は法令上運営者に対応義務がある場合は、この限りではありません。\n7. 本条は、利用者が法令上有する損害賠償請求権、契約の解除権その他の権利を不当に制限するものではありません。\n\n---\n\n## 第28条（利用者の責任）\n\n1. 利用者は、自己の責任において、本規約若しくは個別規程に違反し、又は本サービスの利用に関連して運営者若しくは第三者に損害を与えた場合、適用される法令に従い、その損害について責任を負います。\n2. 利用者の投稿コンテンツ又は利用行為に関して第三者から運営者に請求、通報、訴訟その他の申立てが行われた場合、当該利用者は、運営者から合理的に求められた範囲で、事実確認及び紛争解決に協力するものとします。\n3. 前項の申立てが利用者の故意又は過失による本規約違反に起因し、運営者が損害又は合理的な費用を負担した場合、利用者は、法令上認められる範囲で当該損害又は費用を賠償するものとします。\n4. 本条は、利用者に帰責性がない場合に責任を負わせ、又は利用者の責任を法令上認められる範囲を超えて拡大するものではありません。\n\n---\n\n## 第29条（個人情報等の取扱い）\n\n1. 運営者は、利用者の個人情報その他の利用者に関する情報を、プライバシーポリシーに従って取り扱います。\n2. 利用者の端末から外部事業者へ送信される情報については、外部送信に関する公表事項に定めます。\n3. 利用者は、本サービスを利用する前に、プライバシーポリシー及び外部送信に関する公表事項を確認するものとします。\n4. 運営者は、個人情報の漏えい、滅失又は毀損等の防止その他個人情報の安全管理のため、必要かつ適切な措置を講じます。\n\n---\n\n## 第30条（本規約及び個別規程の変更）\n\n1. 運営者は、次のいずれかに該当する場合、本規約又は個別規程を変更することがあります。\n   1) 変更が利用者の一般の利益に適合する場合\n   2) 変更が利用契約の目的に反せず、変更の必要性、変更後の内容の相当性、変更の内容その他の事情に照らして合理的である場合\n   3) 法令の制定若しくは改廃、行政機関の指針、社会情勢、サービス内容又は技術環境の変化に対応するため、合理的に必要である場合\n2. 運営者は、本規約又は個別規程を変更する場合、次の事項を、本サービス上への掲載、登録された連絡先への通知その他適切な方法により周知します。\n   1) 変更する旨\n   2) 変更後の内容\n   3) 変更の効力発生日\n3. 利用者に重大な影響又は不利益を与える変更については、緊急又はやむを得ない場合を除き、原則として効力発生日の30日前までに周知します。\n4. 第1項の要件を満たさず、利用者の同意を必要とする変更については、運営者は、運営者所定の方法により利用者の同意を取得します。\n5. 変更後の本規約又は個別規程は、周知した効力発生日から適用されます。\n6. 本条は、法令上利用者の個別の同意が必要とされる変更について、当該同意を不要とするものではありません。\n\n---\n\n## 第31条（連絡及び通知）\n\n1. 運営者から利用者への連絡又は通知は、次のいずれかの方法により行います。\n   1) 本サービス上への表示\n   2) 登録された連絡先への送信\n   3) アプリ内通知又はプッシュ通知\n   4) その他運営者が適切と判断する方法\n2. 運営者が登録情報に含まれる連絡先へ通知を送信した場合、通常到達すべき時に利用者へ到達したものとして取り扱うことがあります。ただし、運営者が通知の不達を認識していた場合又は運営者の責めに帰すべき事由により通知が到達しなかった場合は、この限りではありません。\n3. 利用者は、運営者からの重要な通知を受け取るため、登録情報を正確かつ最新の状態に維持するものとします。\n4. 利用者から運営者への連絡は、本サービス上のお問い合わせフォームその他運営者が指定する方法により行うものとします。\n5. 運営者は、利用者からの問い合わせについて、内容、緊急性及び必要性に応じて合理的な範囲で対応します。\n\n---\n\n## 第32条（反社会的勢力の排除）\n\n1. 利用者は、現在及び過去5年間において、自らが次のいずれにも該当しないことを表明し、将来にわたっても該当しないことを保証するものとします。\n   1) 暴力団\n   2) 暴力団員\n   3) 暴力団員でなくなった時から5年を経過していない者\n   4) 暴力団準構成員\n   5) 暴力団関係企業\n   6) 総会屋、社会運動等標ぼうゴロ又は特殊知能暴力集団等\n   7) その他前各号に準ずる者\n2. 利用者は、自ら又は第三者を利用して、次の行為を行わないことを保証するものとします。\n   1) 暴力的な要求行為\n   2) 法的な責任を超えた不当な要求行為\n   3) 脅迫的な言動又は暴力を用いる行為\n   4) 風説を流布し、偽計若しくは威力を用いて運営者の信用を毀損し、又は業務を妨害する行為\n   5) その他前各号に準ずる行為\n3. 運営者は、利用者が本条に違反したと合理的に判断した場合、事前の通知又は催告なく、本サービスの利用停止又はアカウント削除その他必要な措置を講じることがあります。\n4. 前項の措置は、利用者が法令上有する権利を不当に制限するものではありません。\n\n---\n\n## 第33条（権利義務の譲渡）\n\n1. 利用者は、運営者の事前の書面又は電磁的方法による同意なく、利用契約上の地位又は本規約に基づく権利若しくは義務を、第三者に譲渡、移転、担保設定その他の処分をしてはなりません。\n2. 運営者は、本サービスに関する事業を第三者に譲渡し、法人化し、会社分割その他の組織再編を行い、又は相続その他の包括承継が生じた場合、当該事業に必要な範囲で、利用契約上の地位並びに本規約に基づく権利及び義務を承継させることがあります。\n3. 前項の承継が行われる場合、運営者又は承継先は、法令に従い、利用者に対して必要な通知又は公表を行います。\n4. 個人情報その他利用者に関する情報の承継については、プライバシーポリシー及び適用される法令に従います。\n\n---\n\n## 第34条（分離可能性）\n\n1. 本規約又は個別規程の一部の規定が、法令又は裁判所の判断により無効若しくは執行不能と判断された場合であっても、その他の規定は、引き続き有効に存続します。\n2. 前項の場合、無効又は執行不能となった規定は、その趣旨及び目的を可能な限り維持しながら、法令上有効かつ執行可能な範囲で適用されるものとします。\n3. 本規約の一部が特定の利用者との関係で無効又は執行不能となった場合であっても、他の利用者との関係における有効性に当然に影響を与えるものではありません。\n\n---\n\n## 第35条（準拠法及び裁判管轄）\n\n1. 本規約、個別規程及び利用契約の成立、効力、履行及び解釈には、日本法を適用します。\n2. 本サービスに関連して運営者と利用者との間に紛争が生じた場合、双方は、可能な限り誠実に協議し、その解決に努めるものとします。\n3. 協議によって解決しない場合、本サービス、本規約、個別規程又は利用契約に関連する一切の訴訟について、東京地方裁判所又は東京簡易裁判所を、第一審の専属的合意管轄裁判所とします。\n4. 前項は、消費者契約その他について、法令により利用者が別の裁判所へ訴えを提起する権利を有する場合、その権利を不当に制限するものではありません。\n\n---\n\n## 第36条（お問い合わせ）\n\n1. 本サービス、本規約、投稿コンテンツ、権利侵害、個人情報その他に関するお問い合わせは、本サービス上に掲載するお問い合わせフォームその他運営者が指定する窓口から行うものとします。\n2. 権利侵害に関する申出及び通報については、権利侵害・通報ポリシーに従ってください。\n3. 個人情報の開示、訂正、利用停止、削除その他の請求については、プライバシーポリシーに定める方法に従ってください。\n\n---\n\n## 改定履歴\n\n**2026年10月17日／バージョン1.13.0**\n\n本サービスが現時点では無料であり、有料プラン及び定期購入サービスを提供していないことを明確化しました。限定機能は、試験提供、個別の利用許可又はキャンペーン等により提供される場合があることを整理しました。また、レビューの投稿件数に応じて、登録利用者が標準色以外のページカラーを一色ずつ選択して解禁できる条件と、解禁後の取扱いを明確化しました。\n\n**2026年10月14日／バージョン1.12.0**\n\nレビュー本文の文字数上限を、1件につき1000字とすることを明確化しました。\n\n**2026年10月12日／バージョン1.11.0**\n\n書籍の購入先リンクをAmazonアソシエイトから楽天アフィリエイトへ変更し、リンク先及び外部送信情報の説明を更新しました。\n\n**2026年9月4日／バージョン1.10.0**\n\n書籍詳細に表示するAmazonアソシエイト・プログラムへのリンク及び、リンク先で行われる商品取引の取扱いを明確化しました。\n\n**2026年9月2日／バージョン1.9.0**\n\n読了した書籍と「読みたい！」作品を重複して登録できないこと及び読了投稿時に「読みたい！」作品から自動削除されることを明確化しました。\n\n**2026年9月2日／バージョン1.8.0**\n「読みたい！」作品の保存、投稿別の登録数及び通知、反応者一覧並びに自分の投稿へ反応できないことを明確化しました。\n\n**2026年8月30日／バージョン1.7.0**\n退会者の本人確認情報及び削除監査情報を原則90日間保存し、適法な照会又は具体的な紛争等がある場合に法的保存措置を設定する取扱いを明確化しました。\n\n**2026年8月30日／バージョン1.6.0**\nお気に入りの登録上限を通常利用では三冊、限定機能では十二冊とし、ページカラーの全色選択を限定機能とすること及び既存利用者の取扱いを明確化しました。\n\n**2026年8月30日／バージョン1.5.0**\nGoogleアカウントによる登録及びログインの提供開始に合わせ、利用可能な外部認証サービスを更新しました。\n\n**2026年8月28日／バージョン1.4.0**\nフォロー中の登録利用者による新規投稿の通知及び返信のネタバレ表示方法を明確化しました。\n\n**2026年8月27日／バージョン1.3.0**\n返信機能及び限定機能の利用条件を明確化しました。\n\n**2026年8月19日／バージョン1.2.0**\n公開用のユーザーIDを登録後は変更できないこと及びユーザー名をアカウント設定から変更できることを明記しました。\n\n**2026年8月19日／バージョン1.1.0**\nユーザー検索、フォロー、公開範囲及び現行の投稿機能に関する規定を整理し、バージョン表記をセマンティックバージョニングへ移行しました。\n\n**2026年7月25日／バージョン1.0.0**\n本規約を制定しました。\n\n---\n\n## 附則\n\n**制定日**\n2026年7月25日\n\n**最終改定日**\n2026年10月17日\n\n**バージョン**\n1.13.0\n\n**運営者**\n伊能龍之介''';\n\n  @override\n  Widget build(BuildContext context) {\n    final blocks = _parseBlocks(_termsText);\n\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.start,\n      children: [\n        for (final block in blocks) ...[\n          if (block.spacingBefore > 0) SizedBox(height: block.spacingBefore),\n          Padding(\n            padding: EdgeInsets.only(left: block.isBullet ? 12 : 0),\n            child: Text(\n              block.text,\n              style: block.style.copyWith(color: Colors.white),\n            ),\n          ),\n        ],\n        const SizedBox(height: 40),\n      ],\n    );\n  }\n\n  static List<_PolicyBlock> _parseBlocks(String source) {\n    final blocks = <_PolicyBlock>[];\n    var previousLineWasEmpty = false;\n\n    for (final rawLine in source.split('\\n')) {\n      final line = rawLine.trim();\n      if (line.isEmpty) {\n        previousLineWasEmpty = true;\n        continue;\n      }\n      if (line == '---') {\n        previousLineWasEmpty = true;\n        continue;\n      }\n\n      final spacing = previousLineWasEmpty ? 12.0 : 2.0;\n      previousLineWasEmpty = false;\n\n      if (line.startsWith('# ')) {\n        blocks.add(\n          _PolicyBlock(\n            text: line.substring(2),\n            style: _titleStyle,\n            spacingBefore: blocks.isEmpty ? 0 : 20,\n          ),\n        );\n      } else if (line.startsWith('## ')) {\n        blocks.add(\n          _PolicyBlock(\n            text: line.substring(3),\n            style: _headingStyle,\n            spacingBefore: blocks.isEmpty ? 0 : 20,\n          ),\n        );\n      } else if (line.startsWith('### ')) {\n        blocks.add(\n          _PolicyBlock(\n            text: line.substring(4),\n            style: _subheadingStyle,\n            spacingBefore: 12,\n          ),\n        );\n      } else if (line.startsWith('**') && line.endsWith('**')) {\n        blocks.add(\n          _PolicyBlock(\n            text: line.substring(2, line.length - 2),\n            style: _subheadingStyle,\n            spacingBefore: spacing,\n          ),\n        );\n      } else if (line.startsWith('* ')) {\n        blocks.add(\n          _PolicyBlock(\n            text: '• ${line.substring(2).replaceAll('**', '')}',\n            style: _bodyStyle,\n            spacingBefore: 0,\n            isBullet: true,\n          ),\n        );\n      } else {\n        blocks.add(\n          _PolicyBlock(\n            text: line.replaceAll('**', ''),\n            style: _bodyStyle,\n            spacingBefore: spacing,\n          ),\n        );\n      }\n    }\n\n    return blocks;\n  }\n}\n\nclass _PolicyBlock {\n  const _PolicyBlock({\n    required this.text,\n    required this.style,\n    required this.spacingBefore,\n    this.isBullet = false,\n  });\n\n  final String text;\n  final TextStyle style;\n  final double spacingBefore;\n  final bool isBullet;\n}\n",
  "community-guidelines": "import 'package:flutter/material.dart';\n\nclass CommunityGuidelinesScreen extends StatelessWidget {\n  const CommunityGuidelinesScreen({super.key, this.onClose});\n\n  final VoidCallback? onClose;\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      backgroundColor: Colors.black,\n      appBar: AppBar(\n        backgroundColor: Colors.black,\n        foregroundColor: Colors.white,\n        surfaceTintColor: Colors.transparent,\n        title: const Text('コミュニティガイドライン'),\n        leading: IconButton(\n          icon: const Icon(Icons.close),\n          onPressed: onClose ?? () => Navigator.of(context).pop(),\n        ),\n      ),\n      body: const SafeArea(\n        child: SingleChildScrollView(\n          padding: EdgeInsets.symmetric(horizontal: 24, vertical: 20),\n          child: _CommunityGuidelinesContent(),\n        ),\n      ),\n    );\n  }\n}\n\nclass _CommunityGuidelinesContent extends StatelessWidget {\n  const _CommunityGuidelinesContent();\n\n  static const _titleStyle = TextStyle(\n    fontSize: 18,\n    fontWeight: FontWeight.w900,\n    height: 1.5,\n  );\n\n  static const _headingStyle = TextStyle(\n    fontSize: 15,\n    fontWeight: FontWeight.w700,\n    height: 1.7,\n  );\n\n  static const _labelStyle = TextStyle(\n    fontSize: 13,\n    fontWeight: FontWeight.w700,\n    height: 1.7,\n  );\n\n  static const _bodyStyle = TextStyle(\n    fontSize: 13,\n    height: 1.9,\n    color: Colors.white,\n  );\n\n  static const String _guidelinesText = r'''Sharemarium コミュニティガイドライン\n伊能龍之介（以下「運営者」といいます。）は、読書レビューSNS「Sharemarium」（以下「本サービス」といいます。）を、利用者が安心して読書体験や意見を共有できる場所にするため、本コミュニティガイドラインを定めます。\n本ガイドライン中、画像、音声、動画、ダイレクトメッセージ、ミュート又は投稿ごとの公開範囲等、現時点で提供していない機能に関する記載は、当該機能が将来提供された場合に限って適用されます。現時点では、文章によるレビュー、投稿又は返信に対する返信、リアクション、フォロー、アカウント単位の公開・非公開、投稿の通報及びブロック等を提供しています。返信の投稿は、試験提供、個別の利用許可その他運営者が定める条件を満たす登録利用者に限られることがあります。\n本ガイドラインは、Sharemarium利用規約の一部を構成します。本ガイドラインに定めのない事項については、利用規約、権利侵害・通報ポリシー及びプライバシーポリシーが適用されます。\n________________________________________\n1. 基本的な考え方\nSharemariumでは、書籍に対する多様な感想、批評及び評価を尊重します。\n同じ書籍であっても、利用者によって感想や評価が異なることは自然なことです。肯定的な意見だけでなく、否定的な意見や低い評価も、適切な表現で投稿されている限り認められます。\n一方で、書籍に対する批評と、著者、出版社、他の利用者その他の個人に対する攻撃は異なります。\n利用者は、次の原則を意識して本サービスを利用してください。\n1.\t書籍を批評しても、人を攻撃しないこと\n2.\t異なる感想や価値観を尊重すること\n3.\t自分が実際に読んだ内容に基づき、誠実に投稿すること\n4.\t第三者の権利及びプライバシーを尊重すること\n5.\t広告、献本その他の関係がある場合は明確に表示すること\n6.\tネタバレ、年齢制限その他の表示ルールを守ること\n7.\t他の利用者が安心して利用できる環境を損なわないこと\n________________________________________\n2. 誠実なレビューを投稿してください\nレビューは、実際に全部又は一部を読んだ書籍について投稿してください。\nレビュー本文は、1件につき1000字以内で投稿してください。\n次のような投稿は禁止します。\n•\t書籍を読んでいないにもかかわらず、読んだものとして投稿すること\n•\t書籍の内容を確認せず、他人のレビューや要約だけを基に投稿すること\n•\t他人のレビューを、自分の感想であるかのように転載すること\n•\t出版社、著者その他の第三者から指定された評価を、自分の評価であるかのように投稿すること\n•\t書籍、著者、出版社又は利用者の評価を不正に操作する目的で投稿すること\n•\t虚偽の事実を、確認された事実であるかのように記載すること\n書籍の一部のみを読んでレビューする場合は、可能な限り、「途中まで読んだ」「試し読み部分を読んだ」など、そのことが他の利用者に分かるようにしてください。\n感想や評価は主観的なものであり、他の利用者と意見が異なること自体は問題ありません。ただし、事実として記載する内容については、可能な限り正確性を確認してください。\n________________________________________\n3. 正当な批評と誹謗中傷の違い\n書籍、文章表現、構成、テーマ、編集方針その他の作品内容に対する批評は認められます。\n例えば、次のような表現は、文脈や表現方法に問題がない限り、原則として認められます。\n•\t「物語の展開に納得できなかった」\n•\t「説明が分かりにくいと感じた」\n•\t「登場人物の描写が自分には合わなかった」\n•\t「期待していた内容とは違った」\n•\t「評価が高い理由を理解できなかった」\n一方、次のような行為は禁止します。\n•\t著者、出版社、翻訳者、他の利用者その他の個人を侮辱すること\n•\t人格、容姿、経歴、属性その他作品と関係のない事項を攻撃すること\n•\t根拠なく犯罪、不正又は不道徳な行為を行ったと断定すること\n•\t相手を傷つけ、恐怖を与え、又は社会的評価を低下させることを目的とする投稿\n•\t同一人物に対して繰り返し否定的な返信を送ること\n•\t他の利用者を集団で攻撃するよう呼びかけること\n•\t相手に対する嫌がらせ又は報復を目的として低評価や通報を行うこと\n投稿の違反性は、特定の単語だけでなく、投稿全体の文脈、表現方法、対象、反復性及び生じている被害等を考慮して判断します。\n________________________________________\n4. 差別及びヘイト行為の禁止\n次の属性等を理由として、個人又は集団を不当に差別し、侮辱し、排除し、脅迫し、又は危害を加えることを正当化する投稿は禁止します。\n•\t人種\n•\t民族\n•\t国籍\n•\t出身地\n•\t信条又は宗教\n•\t性別\n•\t性的指向\n•\t性自認\n•\t年齢\n•\t障害\n•\t疾病\n•\t社会的身分\n•\t職業\n•\tその他本人が容易に変更できない属性等\n書籍に含まれる差別表現について、批評、研究、報道又は教育等の目的で取り上げることは認められる場合があります。\nただし、その場合でも、差別的な表現を必要以上に繰り返し、差別を支持し、又は対象者を攻撃する目的で利用してはなりません。\n________________________________________\n5. 脅迫、嫌がらせ及びつきまといの禁止\n次の行為は禁止します。\n•\t他の利用者に危害を加える旨を伝えること\n•\t暴力、犯罪又は報復をほのめかすこと\n•\t相手が拒否しているにもかかわらず繰り返し接触すること\n•\tブロックされた後、別のアカウント等を利用して接触すること\n•\t相手を監視していることを示し、恐怖を与えること\n•\t私生活上の情報を利用して相手を脅すこと\n•\t他の利用者に対する攻撃、通報又は個人情報の探索を呼びかけること\n•\t他人のアカウントを標的とした集団的な嫌がらせを行うこと\n生命又は身体に対する具体的で差し迫った危険がある場合は、本サービスへの通報だけでなく、警察その他の適切な機関へ直接連絡してください。\n________________________________________\n6. 個人情報及びプライバシーを守ってください\n本人の同意なく、次のような情報を投稿してはなりません。\n•\t住所\n•\t電話番号\n•\tメールアドレス\n•\t個人用SNSの非公開情報\n•\t正確な現在地\n•\t勤務先又は学校\n•\t本名と匿名アカウントを結び付ける情報\n•\t本人確認書類\n•\t金融機関の口座情報\n•\tクレジットカード情報\n•\t医療、家庭、交友関係その他の私生活上の情報\n•\t未成年者に関する詳細な個人情報\n•\tその他、個人を特定し、又は安全を害するおそれのある情報\nすでにインターネット上で公開されている情報であっても、嫌がらせ、脅迫又は相手に不利益を与える目的で再投稿してはなりません。\n他人が写っている写真、音声又は動画を投稿する場合は、必要に応じて本人の同意を得てください。\n書籍イベントや公共の場所で撮影した画像であっても、無関係な人物の顔、名札、住所その他の情報が写り込んでいないか確認してください。\n________________________________________\n7. 著作権その他の権利を尊重してください\n利用者は、自ら作成したもの、権利者から許可を得たもの又は法令上利用が認められるものに限り投稿してください。\n次のような投稿は禁止します。\n•\t書籍本文の全部又は大部分を掲載すること\n•\t漫画、挿絵、写真又は図表を無断で撮影又は複製して掲載すること\n•\t電子書籍の画面を大量に撮影して掲載すること\n•\t他人のレビュー、記事、画像、音声又は動画を無断転載すること\n•\t違法にアップロードされたコンテンツへのリンクを掲載すること\n•\t書籍を読まなくても内容を代替できる程度に、本文や画像を掲載すること\n書籍本文等を引用する場合は、法令上認められる範囲にとどめ、引用部分と自分の文章を明確に区別し、書名、著者名その他適切な出所を示してください。\n引用を行えば、どのような転載も認められるわけではありません。レビューに必要な範囲を超える引用や、引用部分が投稿の主要部分となっている投稿は、削除等の対象になることがあります。\n書影については、本サービスが正規に取得して表示しているものを利用し、利用者自身が無断で撮影又は転載した画像を投稿しないでください。\n________________________________________\n8. ネタバレを適切に設定してください\n次のような情報を含む投稿又は返信には、ネタバレ表示を設定してください。\n•\t物語の結末\n•\t犯人又は事件の真相\n•\t重要人物の生死\n•\t重大な裏切り又は正体\n•\t作品の中心となる仕掛け\n•\t読書体験を大きく左右する重要な展開\n•\tその他、事前に知ることで読書の楽しみが大きく損なわれる情報\nネタバレを含む文章だけでなく、画像、音声、動画、ユーザー名、プロフィール文その他の表示にも注意してください。\n次の行為は禁止します。\n•\tネタバレ表示を意図的に設定しないこと\n•\t投稿の冒頭やタイトル等、隠すことができない部分に重大なネタバレを記載すること\n•\t他の利用者を驚かせ、又は嫌がらせをする目的でネタバレを投稿すること\n•\t返信欄等を利用して、ネタバレ表示を回避すること\n運営者は、必要に応じて、投稿者への事前の通知なく、ネタバレ表示の追加又は表示方法の変更を行うことがあります。\n________________________________________\n8-1. 返信を利用するときのルール\n返信は、対象となる投稿又は返信に関連する内容を、相手及び他の閲覧者に配慮して投稿してください。返信にも、本ガイドラインのすべての禁止事項が適用されます。\n次の行為は禁止します。\n•\t対象となる投稿又は会話と無関係な内容を繰り返し送ること\n•\t侮辱、威圧、嫌がらせ、差別、性的な勧誘又は一方的な宣伝を目的として返信すること\n•\tブロック、非公開設定又は返信機能の利用制限を、別のアカウントその他の方法で回避すること\n•\tネタバレ表示が適用されない部分に重大なネタバレを記載し、表示制限を回避すること\n•\t他人の氏名、連絡先、非公開情報その他の個人情報を返信に記載すること\n•\t自動化された返信又は同一若しくは類似する返信を大量若しくは反復して投稿すること\n返信を閲覧できることと、返信を投稿できることは異なります。返信ボタンに利用制限が表示される場合、その制限を回避して返信してはなりません。\n鍵アカウントの投稿に対する返信は、対象投稿を閲覧できる者に限って表示されます。返信の内容を、対象投稿を閲覧する権限のない者へ無断で転載又は共有しないでください。\n返信に問題がある場合は、対象返信に設置された報告機能から連絡できます。報告機能では対象を十分に特定できない場合又は権利侵害に関する申出は、お問い合わせ窓口から、対象となる返信を特定できる情報とともに連絡してください。\n________________________________________\n9. 年齢制限対象コンテンツ\nSharemariumでは、18歳未満の利用者を保護するため、成人向け書籍及びその関連投稿の表示を制限することがあります。\n運営者は、書籍の題名、説明、画像、投稿内容、外部から提供された情報、利用者からの通報その他の事情を基に、年齢制限対象コンテンツを判定します。\n判定方法及び基準の詳細は、表示制限の回避を防ぐため公開しないことがあります。\n成人向け書籍に関する投稿\n18歳以上の利用者は、適法に出版又は流通している成人向け書籍について、感想や批評を投稿できる場合があります。\nただし、次の内容は禁止します。\n•\t性行為等を必要以上に具体的又は露骨に描写すること\n•\tわいせつな画像、映像又は音声を投稿すること\n•\t性的な勧誘、出会い又は取引を目的とすること\n•\t児童を性的な対象として描写、賞賛又は正当化すること\n•\t児童の性的搾取又は虐待に関するコンテンツを投稿、共有又は入手しようとすること\n•\t違法に作成又は流通しているコンテンツを紹介又は共有すること\n•\t成人向けコンテンツを18歳未満の利用者へ見せることを目的とすること\n表示制限の回避禁止\n次の行為は禁止します。\n•\t虚偽の生年月日を登録すること\n•\t他人の年齢情報又はアカウントを利用すること\n•\t伏字、記号、異体字、隠語又は画像等を用いて判定を回避すること\n•\t成人向け書籍を別の書籍として登録すること\n•\t書籍名又は投稿内容を意図的に変えて表示制限を回避すること\n年齢制限対象コンテンツが18歳未満の利用者に表示された場合は、通報機能又はお問い合わせ窓口から連絡してください。\n________________________________________\n10. 生成AIの利用\n利用者は、レビューの構成整理、文章の校正、表現の提案その他の補助として、生成AIを利用できます。\nただし、生成AIを利用した場合も、投稿内容についての責任は投稿者本人が負います。\n次の行為は禁止します。\n•\t書籍を読まず、生成AIだけでレビューを作成して投稿すること\n•\t生成AIが作成した架空の読書経験を、自分の経験として投稿すること\n•\t事実確認をせず、生成AIの回答をそのまま投稿すること\n•\t実在の人物が発言又は作成したと誤認させる内容を投稿すること\n•\t生成AIを利用して他人の文章を模倣又は無断複製すること\n•\t自動生成したレビュー、返信その他の投稿を大量又は反復して投稿すること\n•\t生成AIを利用して嫌がらせ、スパム又は不正な評価操作を行うこと\n•\t第三者の個人情報又は秘密情報を生成AIへ不適切に入力すること\n運営者が、投稿の透明性又は不正利用防止のため合理的に必要と判断した場合、生成AIを利用した旨の表示を求めることがあります。\n________________________________________\n11. PR、献本及び利害関係の表示\n出版社、著者、書店、販売事業者その他の関係者から、次のような利益を受けて投稿する場合は、その関係が利用者に分かるよう明確に表示してください。\n•\t金銭又は報酬\n•\t献本\n•\t商品又はサービスの無償提供\n•\t割引\n•\t招待\n•\tポイント\n•\tアフィリエイト報酬\n•\tその他の経済的利益\n表示には、内容に応じて、次のような分かりやすい表現を使用してください。\n•\t「広告」\n•\t「PR」\n•\t「献本」\n•\t「出版社から提供を受けました」\n•\t「著者から書籍の提供を受けました」\n•\t「アフィリエイトリンクを含みます」\nプロフィールだけに関係性を記載し、個々の投稿では表示しない方法は、利用者が関係性を認識しにくいため、原則として十分ではありません。\n次の行為は禁止します。\n•\t広告又は宣伝であることを隠すこと\n•\t利益を受けているにもかかわらず、完全に自発的な感想であるかのように表示すること\n•\t分かりにくい場所、表現又はハッシュタグで関係性を隠すこと\n•\t広告主等の指示に従い、不自然な高評価又は虚偽の評価を投稿すること\n利益の提供を受けた場合でも、率直な感想を投稿することはできます。\n________________________________________\n12. スパム及び過度な宣伝の禁止\n次の行為は禁止します。\n•\t同一又は類似する投稿を大量又は反復して投稿すること\n•\t内容と無関係なリンクを掲載すること\n•\t返信欄等で繰り返し商品、サービス又はアカウントを宣伝すること\n•\t他の利用者へ一方的に勧誘メッセージを送ること\n•\tアフィリエイトリンク又は紹介コードの掲載を主な目的として投稿すること\n•\t悪質な情報商材、投資、金融商品、連鎖販売取引その他の勧誘を行うこと\n•\tマルウェア、フィッシングサイトその他危険なウェブサイトへ誘導すること\n•\t検索結果等を操作する目的で、無関係な単語又はタグを大量に付けること\n著者、出版社、書店その他の事業者が本サービスを利用する場合も、本ガイドラインが適用されます。\n運営者が認める公式アカウント又は広告機能等を除き、宣伝だけを目的とする利用は制限されることがあります。\n________________________________________\n13. リアクション、評価及びフォローの不正操作\nリアクション、評価、フォローその他の数値は、利用者の自然な意思に基づいて行われなければなりません。\n次の行為は禁止します。\n•\t複数のアカウントを利用して、自分又は第三者の投稿に反応すること\n•\tボット又は自動操作によってリアクション等を増減させること\n•\t金銭、物品、ポイントその他の利益と引き換えに反応を依頼すること\n•\t相互評価又は相互リアクションを組織的に行うこと\n•\t特定の書籍、著者、出版社又は利用者の評価を不当に上げ下げすること\n•\t低評価、フォロー解除又は通報等を用いて相手を脅すこと\n•\t第三者に集団的な評価操作を呼びかけること\n•\t不正操作を行うサービスを利用又は提供すること\n運営者は、不正なリアクション、評価又はフォローを無効化し、表示上の数値を修正することがあります。\n________________________________________\n14. なりすまし及びアカウントの不正利用\n次の行為は禁止します。\n•\t他の利用者、著者、出版社、書店、団体又は運営者になりすますこと\n•\t公認、公式、提携又は関係者であると誤認させること\n•\t他人の氏名、プロフィール画像又は経歴を無断で使用すること\n•\t他人のアカウントを利用すること\n•\t自分のアカウントを第三者へ譲渡、販売、貸与又は共有すること\n•\t利用停止等を回避するため、新しいアカウントを作成すること\n•\t不正な目的で複数のアカウントを作成又は使用すること\nパロディ、ファン又は非公式のアカウントを作成する場合は、本人又は公式アカウントであると誤認されないよう、プロフィール等に明確に表示してください。\n________________________________________\n15. 違法、有害又は危険な行為\n次の内容は禁止します。\n•\t犯罪の実行を具体的に勧誘、依頼又は支援すること\n•\t武器、違法薬物その他の違法な物品又はサービスを取引すること\n•\t詐欺、フィッシング、アカウントの窃取その他の不正行為\n•\tマルウェア又は有害なプログラムを配布すること\n•\t不正アクセスの方法又は認証回避の情報を、犯罪目的で提供すること\n•\t人身取引、性的搾取又は児童虐待を助長すること\n•\tテロ行為又は重大な暴力行為を具体的に支援又は勧誘すること\n•\tその他法令に違反する行為\n犯罪、暴力、薬物その他の問題を扱う書籍について、批評、研究、教育、報道又は被害防止の目的で議論することは認められる場合があります。\nその場合でも、犯罪を実行する目的の具体的な支援や勧誘は認められません。\n________________________________________\n16. 自殺及び自傷行為に関する投稿\n自殺、自傷行為、摂食障害その他生命又は身体に重大な危険を及ぼす行為について、体験、回復、支援又は書籍の内容を話し合うことはできます。\nただし、次の内容は禁止します。\n•\t自殺又は自傷行為を推奨、称賛又は美化すること\n•\t他人に自殺又は自傷行為を促すこと\n•\t実行方法を具体的かつ実用的に説明すること\n•\t危険な行為への参加者を募集すること\n•\t自殺又は自傷行為を用いて他人を脅すこと\n•\t支援を求めている利用者を侮辱又は追い詰めること\n生命又は身体に差し迫った危険があると運営者が判断した場合、投稿の非表示、アカウントの一時制限、関係機関への相談その他必要な措置を講じることがあります。\n________________________________________\n17. セキュリティ及びサービス運営の妨害\n次の行為は禁止します。\n•\t本サービスへの不正アクセス又はその試み\n•\t他人の認証情報を取得又は使用すること\n•\tセキュリティ機能又はアクセス制限を回避すること\n•\t本サービスの脆弱性を不正な目的で探索又は悪用すること\n•\t本サービスへ過度な負荷を与えること\n•\tマルウェアその他の有害なプログラムを送信すること\n•\t運営者の許可なく、スクレイピング、クローリング又はボット等を用いて情報を大量に取得すること\n•\t運営者の許可なく、本サービス上の情報を生成AI又は機械学習の学習用データとして大量に収集すること\n•\tリバースエンジニアリングその他の方法で内部構造を解析すること\n•\t不具合を自己又は第三者の利益のために悪用すること\n•\t通報、問い合わせ又は異議申立ての制度を妨害又は濫用すること\nセキュリティ上の問題を発見した場合は、公に拡散したり悪用したりせず、お問い合わせ窓口から運営者へ連絡してください。\n________________________________________\n18. 通報及びブロック\n本ガイドラインに違反するおそれのある投稿又は利用者を発見した場合は、通報機能又はお問い合わせ窓口から連絡してください。\n通報の際は、可能な範囲で次の情報を提供してください。\n•\t対象となる投稿又はアカウント\n•\t通報理由\n•\t問題となる具体的な箇所\n•\t問題が発生した日時又は経緯\n•\t必要に応じて画面の記録その他の資料\n通報が行われたことのみを理由として、投稿の削除又はアカウントの停止が行われるものではありません。\n嫌がらせ、報復、競争相手の排除その他不当な目的による虚偽又は濫用的な通報は禁止します。\n利用者は、ブロック機能等を利用して、特定の利用者との接触又は表示を制限できます。ただし、ブロックによって公開情報の閲覧や第三者を介した接触を完全に防止できるとは限りません。\n________________________________________\n19. 違反に対する措置\n運営者は、投稿コンテンツ又は利用行為が、本ガイドライン、利用規約若しくは法令に違反し、第三者の権利を侵害し、又は本サービスの安全な運営を害すると合理的に判断した場合、違反の内容及び程度に応じて、次の措置を講じることがあります。\n1.\t注意又は警告\n2.\t投稿の修正要請\n3.\tネタバレ表示、警告表示又は年齢制限の追加\n4.\t投稿の公開範囲の変更\n5.\t検索結果その他の表示領域への表示制限\n6.\t投稿の一時的な非表示\n7.\t投稿の削除\n8.\tリアクション、返信、フォローその他の機能の制限\n9.\t不正なリアクション、評価又はフォローの無効化\n10.\tアカウントの一時停止\n11.\tアカウントの削除\n12.\t関係する記録の保存\n13.\t警察その他の関係機関への相談又は通報\n14.\tその他、被害防止又は本サービスの安全な運営に必要な措置\n運営者は、措置を判断する際、次の事情を考慮するよう努めます。\n•\t投稿全体の文脈\n•\t違反の重大性\n•\t故意又は過失の程度\n•\t違反の反復性\n•\t生じている又は生じるおそれのある被害\n•\t過去の警告又は措置の有無\n•\t投稿の公益性、批評性又は教育目的\n•\tその他関連する事情\n緊急性が高い場合、被害の拡大を防ぐ必要がある場合又はセキュリティ上の危険がある場合は、事前の通知なく暫定措置を講じることがあります。\n________________________________________\n20. 措置に対する異議申立て\n投稿の非表示若しくは削除、機能制限、アカウント停止その他の措置を受けた登録利用者は、運営者が指定する方法及び期間内に異議を申し立てることができます。\n異議申立てには、次の情報を含めてください。\n•\t対象となる措置\n•\t異議を申し立てる理由\n•\t判断に誤りがあると考える具体的な事情\n•\t投稿又は利用が適切であると考える理由\n•\t必要な権利又は許諾を有していることを示す資料\n•\tその他、再確認に必要な情報\n運営者は、提出された情報を確認し、必要に応じて、措置を維持、変更又は取り消します。\n同一の措置について十分な検討が行われ、新たな事実又は資料が提示されていない場合は、繰り返し行われる異議申立てを受け付けないことがあります。\n________________________________________\n21. 本ガイドラインの変更\n運営者は、法令の制定若しくは改廃、本サービスの内容変更、利用状況又は社会情勢の変化その他必要がある場合、本ガイドラインを変更することがあります。\n変更後の内容及び効力発生日は、本サービス上への掲載その他適切な方法により周知します。\n利用者に重大な影響又は不利益を与える変更については、緊急又はやむを得ない場合を除き、原則として効力発生日の30日前までに周知します。\n法令上又は利用規約上、利用者の同意が必要となる変更については、変更後の内容を適用する前に必要な同意を取得します。\n________________________________________\n22. お問い合わせ\n本ガイドライン、投稿の取扱い、通報又は異議申立てに関するお問い合わせは、本サービス上のお問い合わせフォームからご連絡ください。\n運営者\n伊能龍之介\nサービス名\nSharemarium\nお問い合わせ方法\n本サービス上のお問い合わせフォーム\n________________________________________\n改定履歴\n2026年10月14日／バージョン1.4.0\nレビュー本文の文字数上限を、1件につき1000字とすることを明確化しました。\n2026年8月28日／バージョン1.3.0\n返信にもネタバレ表示を設定し、閲覧者が表示操作を行うまで本文を隠すルールを明確化しました。\n2026年8月28日／バージョン1.2.0\n返信単位の報告機能及びお問い合わせ窓口との使い分けを明確化しました。\n2026年8月27日／バージョン1.1.0\n返信機能の適用範囲、利用条件、禁止行為、公開範囲及び問題がある返信の連絡方法を明確化しました。\n2026年8月17日／バージョン1.0.1\n現時点で提供する機能と将来提供する機能の適用範囲を明確化しました。\n2026年7月25日／バージョン1.0.0\n本ガイドラインを制定しました。\n________________________________________\n附則\n制定日\n2026年7月25日\n最終改定日\n2026年10月14日\nバージョン\n1.4.0\n運営者\n伊能龍之介''';\n\n  @override\n  Widget build(BuildContext context) {\n    final blocks = _parseBlocks(_guidelinesText);\n\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.start,\n      children: [\n        for (final block in blocks) ...[\n          if (block.spacingBefore > 0) SizedBox(height: block.spacingBefore),\n          Padding(\n            padding: EdgeInsets.only(left: block.isBullet ? 12 : 0),\n            child: Text(\n              block.text,\n              style: block.style.copyWith(color: Colors.white),\n            ),\n          ),\n        ],\n        const SizedBox(height: 40),\n      ],\n    );\n  }\n\n  static List<_GuidelinesBlock> _parseBlocks(String source) {\n    final blocks = <_GuidelinesBlock>[];\n    var nextLineIsSectionHeading = false;\n    const labels = {'運営者', 'サービス名', 'お問い合わせ方法', '制定日', '最終改定日', 'バージョン'};\n\n    for (final rawLine in source.split('\\n')) {\n      final line = rawLine.trim();\n      if (line.isEmpty) {\n        continue;\n      }\n      if (RegExp(r'^_+$').hasMatch(line)) {\n        nextLineIsSectionHeading = true;\n        continue;\n      }\n\n      if (blocks.isEmpty) {\n        blocks.add(\n          _GuidelinesBlock(text: line, style: _titleStyle, spacingBefore: 0),\n        );\n      } else if (nextLineIsSectionHeading) {\n        nextLineIsSectionHeading = false;\n        blocks.add(\n          _GuidelinesBlock(text: line, style: _headingStyle, spacingBefore: 20),\n        );\n      } else if (labels.contains(line)) {\n        blocks.add(\n          _GuidelinesBlock(text: line, style: _labelStyle, spacingBefore: 10),\n        );\n      } else if (line.startsWith('•')) {\n        blocks.add(\n          _GuidelinesBlock(\n            text: line,\n            style: _bodyStyle,\n            spacingBefore: 0,\n            isBullet: true,\n          ),\n        );\n      } else {\n        blocks.add(\n          _GuidelinesBlock(text: line, style: _bodyStyle, spacingBefore: 6),\n        );\n      }\n    }\n\n    return blocks;\n  }\n}\n\nclass _GuidelinesBlock {\n  const _GuidelinesBlock({\n    required this.text,\n    required this.style,\n    required this.spacingBefore,\n    this.isBullet = false,\n  });\n\n  final String text;\n  final TextStyle style;\n  final double spacingBefore;\n  final bool isBullet;\n}\n",
  "infringement-policy": "import 'package:flutter/material.dart';\n\nclass InfringementPolicyScreen extends StatelessWidget {\n  const InfringementPolicyScreen({super.key, this.onClose});\n\n  final VoidCallback? onClose;\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      backgroundColor: Colors.black,\n      appBar: AppBar(\n        backgroundColor: Colors.black,\n        foregroundColor: Colors.white,\n        surfaceTintColor: Colors.transparent,\n        title: const Text('権利侵害・通報ポリシー'),\n        leading: IconButton(\n          icon: const Icon(Icons.close),\n          onPressed: onClose ?? () => Navigator.of(context).pop(),\n        ),\n      ),\n      body: const SafeArea(\n        child: SingleChildScrollView(\n          padding: EdgeInsets.symmetric(horizontal: 24, vertical: 20),\n          child: _InfringementPolicyContent(),\n        ),\n      ),\n    );\n  }\n}\n\nclass _InfringementPolicyContent extends StatelessWidget {\n  const _InfringementPolicyContent();\n\n  static const _titleStyle = TextStyle(\n    fontSize: 18,\n    fontWeight: FontWeight.w900,\n    height: 1.5,\n  );\n\n  static const _headingStyle = TextStyle(\n    fontSize: 15,\n    fontWeight: FontWeight.w700,\n    height: 1.7,\n  );\n\n  static const _labelStyle = TextStyle(\n    fontSize: 13,\n    fontWeight: FontWeight.w700,\n    height: 1.7,\n  );\n\n  static const _bodyStyle = TextStyle(\n    fontSize: 13,\n    height: 1.9,\n    color: Colors.white,\n  );\n\n  static const String _policyText = r'''Sharemarium 権利侵害・通報ポリシー\n伊能龍之介（以下「運営者」といいます。）は、読書レビューSNS「Sharemarium」（以下「本サービス」といいます。）において、利用者及び第三者の権利を尊重し、安全で健全な利用環境を維持するため、権利侵害に関する申出及び本サービス上の通報を、以下のとおり取り扱います。\n本ポリシーは、Sharemarium利用規約の一部を構成します。本ポリシーに定めのない事項については、利用規約、コミュニティガイドライン及びプライバシーポリシーが適用されます。\n________________________________________\n第1条（目的）\n本ポリシーは、次の事項を定めることを目的とします。\n1.\t本サービス上の違反行為又は不適切なコンテンツを通報する方法\n2.\t著作権、名誉、プライバシーその他の権利侵害について対応を申し出る方法\n3.\t通報及び申出を受けた場合の確認及び対応手順\n4.\t投稿者による意見提出及び異議申立ての方法\n5.\t通報者、権利者、投稿者その他の関係者に関する情報の取扱い\n________________________________________\n第2条（通報と権利侵害に関する申出の区分）\n1.\t本ポリシーにおける「通報」とは、本サービス上の投稿コンテンツ又は利用行為が、利用規約若しくはコミュニティガイドラインに違反し、又は安全上問題があると考える者が、運営者に確認を求めることをいいます。\n2.\t本ポリシーにおける「権利侵害に関する申出」とは、自己又は自己が適法に代理する第三者の権利若しくは利益が侵害されていると考える者が、投稿コンテンツの削除、非表示その他の対応を求めることをいいます。\n3.\t一般の利用者は、自己の権利が直接侵害されていない場合であっても、本サービス上の通報機能を利用できます。\n4.\t著作権、名誉、プライバシーその他の権利侵害を理由として正式な対応を求める場合、原則として、権利者本人又は権利者から適法に委任を受けた代理人が申出を行うものとします。\n5.\t運営者は、通報又は申出の名称にかかわらず、その内容に応じて適切な手続に振り分けることがあります。\n________________________________________\n第3条（通報できる内容）\n利用者は、次の内容又は行為について通報できます。\n1.\t誹謗中傷、侮辱、脅迫又は嫌がらせ\n2.\t差別的な表現又は差別を助長する行為\n3.\tなりすまし\n4.\t個人情報又は私生活上の情報の無断公開\n5.\t著作権、商標権、肖像権その他の権利を侵害するおそれのある投稿\n6.\tスパム、宣伝、勧誘又は同一内容の大量投稿\n7.\t虚偽レビュー又はレビュー、評価若しくはリアクションの不正操作\n8.\t広告、PR、献本その他の利害関係を隠した投稿\n9.\t違法又は有害なコンテンツ\n10.\t児童の性的搾取又は虐待に関するコンテンツ\n11.\t年齢制限又はネタバレ表示を意図的に回避する投稿\n12.\t不正アクセス、ボット、スクレイピングその他本サービスの運営を妨害する行為\n13.\t自殺、自傷行為その他生命又は身体に差し迫った危険を生じさせる内容\n14.\t利用規約又はコミュニティガイドラインに違反するその他の内容\n15.\tその他、利用者又は第三者の安全若しくは権利を害するおそれのある内容\n________________________________________\n第4条（通報方法）\n1.\t一般的な規約違反は、対象となる投稿又は返信に設置された報告機能から通報できます。プロフィール、アカウント、権利侵害その他報告機能では対象を十分に特定できない申出は、運営者が指定するお問い合わせ窓口から行うことができます。返信に関する連絡では、対象投稿、返信者、返信日時、返信本文又は画面の記録その他対象を特定できる情報を提供してください。\n2.\t通報者は、可能な範囲で、次の情報を提供してください。\n1.\t対象となる投稿コンテンツ又はアカウント\n2.\t対象を確認できるURLその他の識別情報\n3.\t通報理由\n4.\t問題となる具体的な箇所\n5.\t問題が発生した日時又は経緯\n6.\t必要に応じて、画面の記録その他の資料\n7.\tその他、運営者が確認に必要とする情報\n3.\t一般的な規約違反の通報については、運営者が認める範囲で、通報者の氏名その他の本人確認情報を入力せずに通報できる場合があります。\n4.\t匿名の通報又は情報が不足している通報についても確認することがありますが、事実確認が困難な場合、対応できないことがあります。\n5.\t同一の内容について複数の通報が行われたことのみをもって、規約違反又は権利侵害があると判断するものではありません。\n________________________________________\n第5条（権利侵害に関する申出方法）\n1.\t自己の権利又は利益が侵害されていると考える者は、運営者が指定するお問い合わせ窓口から、権利侵害に関する申出を行うことができます。\n2.\t申出者は、原則として、次の情報を提供してください。\n1.\t申出者の氏名又は名称\n2.\t連絡先\n3.\t対象となる投稿コンテンツのURLその他の識別情報\n4.\t問題となる具体的な箇所\n5.\t侵害されたとする権利又は利益の内容\n6.\t権利侵害であると考える具体的な理由\n7.\t申出者が権利者本人であることを確認できる情報\n8.\t代理人が申出を行う場合は、委任状その他代理権を確認できる資料\n9.\t希望する対応\n10.\tその他、運営者が確認に必要とする情報\n3.\t運営者は、権利者本人又は適法な代理人であることを確認するため、本人確認書類、委任状その他必要な資料の提出を求めることがあります。\n4.\t本人確認書類を提出する場合は、運営者が指定する場合を除き、確認に不要な個人番号、保険者番号その他の情報をマスキングしてください。\n5.\t情報又は資料が不足している場合、運営者は申出者に対して追加提出を求めることがあります。必要な情報が提供されない場合、対応を開始又は継続できないことがあります。\n6.\t運営者が申出を受領したことは、権利侵害の存在又は申出内容の正当性を認めたことを意味しません。\n________________________________________\n第6条（著作権侵害に関する申出）\n1.\t著作権又は著作隣接権の侵害を理由とする申出を行う場合、申出者は、第5条に定める情報に加えて、可能な範囲で次の情報を提供してください。\n1.\t権利を有する著作物の名称及び内容\n2.\t著作者又は権利者の氏名若しくは名称\n3.\t正規の著作物を確認できるURL、出版物その他の資料\n4.\t問題となる投稿コンテンツが著作物を利用している具体的な箇所\n5.\t当該利用が許諾、引用その他法令上認められる利用に該当しないと考える理由\n6.\t申出者が著作権者、著作隣接権者又は適法な代理人であることを示す資料\n2.\t著作者であることと、著作権を現在保有していることが一致しない場合があります。運営者は、著作権の譲渡、相続、出版契約、利用許諾その他の権利関係を確認する資料の提出を求めることがあります。\n3.\t書籍の題名、短い表現、アイデア、事実又は一般的な作風等については、著作権による保護の対象となるかが明確でない場合があります。運営者は、必要に応じて追加の説明又は専門家による資料を求めることがあります。\n4.\t引用、批評、研究その他法令上認められる利用に該当する可能性がある場合、運営者は、投稿者の意見及び投稿全体の文脈を確認した上で対応を判断します。\n5.\t著作権侵害の有無について専門的な判断が必要となり、運営者のみでは判断が困難な場合、申出者に対して、弁護士への相談、裁判所の手続その他の法的手段を案内することがあります。\n________________________________________\n第7条（名誉、信用及びプライバシーに関する申出）\n1.\t名誉、信用又はプライバシーの侵害を理由とする申出を行う場合、申出者は、可能な範囲で次の事項を説明してください。\n1.\t対象となる記載\n2.\t当該記載が申出者に関するものであること\n3.\t記載された内容が虚偽であると考える場合は、その理由\n4.\t当該記載によって生じている具体的な不利益\n5.\t公開を望まない私生活上の情報の内容\n6.\t当該情報が既に一般に公開されているかどうか\n7.\t投稿の公益性又は公共性に関する事情\n8.\tその他、権利侵害の判断に必要な事情\n2.\t単に不快であること、批判的であること、評価が低いこと又は自己の見解と異なることのみを理由として、投稿を削除するものではありません。\n3.\t書籍、著者、出版社、書店その他に対する正当な批評、論評又は意見については、表現の内容、根拠、文脈及び公益性等を考慮して判断します。\n4.\t住所、電話番号、連絡先、正確な位置情報その他、公開によって生命、身体又は生活の安全に危険が生じるおそれが高い情報については、暫定的な非表示その他の緊急措置を優先することがあります。\n________________________________________\n第8条（商標、肖像その他の権利に関する申出）\n1.\t商標権の侵害を理由とする申出では、登録商標、登録番号、指定商品若しくは役務及び問題となる使用態様を示してください。\n2.\t肖像権又はパブリシティ権の侵害を理由とする申出では、対象となる人物、画像若しくは動画及び無断利用であると考える理由を示してください。\n3.\t営業秘密、契約上の秘密保持義務その他の権利又は利益を理由とする申出では、秘密として管理されていたこと及び対象情報の公開が不適切であると考える理由を示してください。\n4.\t権利の成立、帰属又は侵害の有無について判断が困難な場合、運営者は、専門家の意見、裁判所の判断その他の資料を求めることがあります。\n________________________________________\n第9条（緊急性の高い通報）\n1.\t次の内容については、運営者が緊急性の高い通報として優先的に確認する場合があります。\n1.\t生命又は身体に対する具体的かつ差し迫った脅迫\n2.\t自殺又は自傷行為の具体的な予告\n3.\t児童の性的搾取又は虐待に関するコンテンツ\n4.\t住所、現在地その他安全上重大な危険を生じさせる個人情報の公開\n5.\t不正アクセス、アカウント乗っ取り又は情報漏えい\n6.\t犯罪行為の具体的な予告\n7.\tその他、緊急に被害を防止する必要がある内容\n2.\t生命又は身体に差し迫った危険がある場合、本サービスへの通報だけでなく、警察、消防、医療機関その他の適切な公的機関へ直接連絡してください。\n3.\t運営者は、緊急性があると合理的に判断した場合、事前の通知なく投稿の暫定非表示、アカウントの一時停止、証拠の保存その他必要な措置を講じることがあります。\n4.\t運営者は、法令に基づく場合又は生命、身体若しくは財産の保護のために必要な場合、警察その他の関係機関へ情報を提供することがあります。\n________________________________________\n第10条（通報及び申出の確認）\n1.\t運営者は、通報又は申出を受領した場合、提供された情報、対象となる投稿コンテンツ、投稿の文脈、当事者から提出された資料その他の事情を確認します。\n2.\t運営者は、確認のため必要がある場合、通報者、申出者、投稿者その他の関係者に対して、追加の説明又は資料を求めることがあります。\n3.\t運営者は、法令違反、権利侵害又は利用規約違反の有無を確認するため、自動的又は機械的な判定を補助的に使用することがあります。\n4.\t通報又は申出の件数が多いことのみを理由として、違反又は権利侵害があると判断するものではありません。\n5.\t通報又は申出の内容が不明確である場合、当事者間で事実関係に重大な争いがある場合又は専門的な法律判断を必要とする場合、運営者は直ちに最終判断を行わないことがあります。\n6.\t運営者は、通報又は申出を合理的な期間内に確認するよう努めます。ただし、内容の複雑さ、資料の不足、当事者への照会その他の事情により、確認に時間を要する場合があります。\n________________________________________\n第11条（暫定措置）\n1.\t運営者は、次のいずれかに該当すると合理的に判断した場合、最終的な確認が完了する前に、必要な範囲で暫定措置を講じることがあります。\n1.\t被害が継続又は拡大するおそれがある場合\n2.\t生命、身体、財産又はプライバシーに重大な危険がある場合\n3.\t明白な規約違反又は権利侵害が疑われる場合\n4.\t証拠の隠滅又は投稿の拡散を防ぐ必要がある場合\n5.\t法令、裁判所又は公的機関から対応を求められた場合\n6.\tその他、本サービスの安全を確保するため緊急の対応が必要な場合\n2.\t暫定措置には、次のものが含まれます。\n1.\t投稿コンテンツの一時的な非表示\n2.\t検索結果その他の表示領域への表示制限\n3.\t公開範囲の変更\n4.\t警告表示、ネタバレ表示又は年齢制限の追加\n5.\t返信、リアクション、投稿その他の機能の一時制限\n6.\tアカウントの一時停止\n7.\t関連する記録の保存\n8.\tその他被害の防止に必要な措置\n3.\t暫定措置は、権利侵害又は規約違反の存在を最終的に認定するものではありません。\n4.\t運営者は、確認の結果に応じて、暫定措置を解除、変更又は正式な措置へ移行します。\n________________________________________\n第12条（投稿者への照会）\n1.\t運営者は、事実関係及び権利関係を確認するため、対象となる投稿コンテンツを投稿した利用者に対し、申出の内容を通知し、意見又は資料の提出を求めることがあります。\n2.\t投稿者への通知には、原則として次の情報が含まれます。\n1.\t対象となる投稿コンテンツ\n2.\t問題とされている箇所\n3.\t申出の理由の概要\n4.\t意見又は資料の提出方法\n5.\t回答期限\n6.\t回答がない場合に講じる可能性のある措置\n3.\t運営者は、通報者又は申出者の氏名、連絡先、本人確認書類その他の情報を、投稿者への照会に必要な範囲を超えて開示しません。\n4.\t次の場合、運営者は投稿者への事前の照会又は通知を行わずに措置を講じることがあります。\n1.\t緊急性が高い場合\n2.\t通知によって申出者その他の第三者の安全が害されるおそれがある場合\n3.\t証拠の隠滅又は被害の拡大のおそれがある場合\n4.\t明白な違法情報又は重大な規約違反である場合\n5.\t法令又は公的機関から通知を制限されている場合\n6.\tその他、事前の照会を行わない合理的な理由がある場合\n5.\t投稿者が期限までに回答しなかったことのみをもって、直ちに権利侵害があると確定するものではありません。ただし、運営者は、確認できる情報に基づいて対応を判断することがあります。\n________________________________________\n第13条（運営者が講じる措置）\n運営者は、確認の結果、利用規約若しくはコミュニティガイドラインへの違反、法令違反、権利侵害又は安全上の問題があると合理的に判断した場合、必要かつ相当な範囲で、次の措置を講じることがあります。\n1.\t投稿者に対する注意又は警告\n2.\t投稿コンテンツの修正要請\n3.\tネタバレ表示、警告表示又は年齢制限の追加\n4.\t公開範囲の変更\n5.\t検索結果その他の表示領域への表示制限\n6.\t投稿コンテンツの一部又は全部の非表示\n7.\t投稿コンテンツの削除\n8.\t返信、リアクション、フォロー、投稿その他の機能の制限\n9.\tアカウントの一時停止\n10.\tアカウントの削除\n11.\t不正利用又は権利侵害に関連する情報の保存\n12.\t警察その他の関係機関への相談又は通報\n13.\tその他、被害の防止又は本サービスの安全な運営に必要な措置\n________________________________________\n第14条（正当な批評及び意見）\n1.\t運営者は、投稿が批判的、否定的又は低評価であることのみを理由として、当該投稿を削除又は制限しません。\n2.\t書籍、著者、出版社、書店その他に対する正当な感想、批評、論評又は意見は、法令、利用規約及びコミュニティガイドラインに違反しない限り認められます。\n3.\t運営者は、対応を判断する際、表現の内容だけでなく、投稿全体の文脈、事実と意見の区別、根拠の有無、公益性、表現方法及び生じている被害等を考慮するよう努めます。\n4.\t権利者又は関係者から削除要請があったことのみを理由として、正当な批評又は意見を自動的に削除するものではありません。\n________________________________________\n第15条（判断結果の通知）\n1.\t運営者は、通報又は権利侵害に関する申出への対応が完了した場合、合理的な範囲で通報者又は申出者に結果を通知します。\n2.\t運営者が投稿コンテンツの削除、利用制限又はアカウント停止等の措置を講じた場合、原則として、対象となった投稿者に措置の内容及び主な理由を通知します。\n3.\t次の情報については、通知しないことがあります。\n1.\t他の利用者又は第三者の個人情報\n2.\t通報者を特定し得る情報\n3.\t運営者のセキュリティ又は不正検知に関する情報\n4.\t公開により調査又は公的機関の手続を妨げる情報\n5.\t法令又は公的機関から開示を制限されている情報\n6.\tその他、開示することが適切でない情報\n4.\t運営者は、個別の法的判断、内部の審査方法又はすべての判断理由を詳細に開示する義務を負うものではありません。\n________________________________________\n第16条（異議申立て）\n1.\t投稿コンテンツの非表示若しくは削除、機能制限、アカウント停止その他の措置を受けた登録利用者は、運営者が指定する方法及び期間内に異議を申し立てることができます。\n2.\t異議申立てには、次の情報を含めてください。\n1.\t対象となる措置\n2.\t異議を申し立てる理由\n3.\t当初の判断に誤りがあると考える具体的な事情\n4.\t投稿又は利用が適法かつ規約に適合すると考える理由\n5.\t必要な権利又は許諾を有していることを示す資料\n6.\tその他、再確認に必要な情報\n3.\t運営者は、異議申立ての内容及び提出された資料を確認し、必要に応じて、措置を維持、変更又は取り消します。\n4.\t運営者は、可能な範囲で、当初の判断に直接関与していない者による確認その他、公平性に配慮した方法で再確認するよう努めます。\n5.\t同一の措置について既に十分な検討が行われ、新たな事実又は資料が提示されていない場合、運営者は、繰り返し行われる異議申立てを受け付けないことがあります。\n6.\t異議申立てを行ったことのみを理由として、登録利用者を不利益に取り扱うことはありません。ただし、異議申立て制度を嫌がらせ、虚偽申告又は業務妨害の目的で利用した場合は、この限りではありません。\n________________________________________\n第17条（虚偽又は濫用的な通報等）\n1.\t通報者及び申出者は、提供する情報が自己の知る限り正確であり、通報又は申出が正当な目的に基づくものであることを確認した上で手続を行うものとします。\n2.\t次の行為は禁止します。\n1.\t虚偽であることを知りながら通報又は申出を行う行為\n2.\t嫌がらせ、報復、競争相手の排除その他不当な目的で手続を利用する行為\n3.\t他人になりすまして通報又は申出を行う行為\n4.\t偽造又は改ざんした資料を提出する行為\n5.\t合理的な理由なく同一又は類似の通報を繰り返す行為\n6.\t通報又は申出と引き換えに金銭その他の利益を要求する行為\n7.\tその他、通報制度又は権利侵害対応制度を濫用する行為\n3.\t運営者は、虚偽又は濫用的な通報等を確認した場合、通報機能の制限、アカウントの利用制限又は削除その他必要な措置を講じることがあります。\n4.\t虚偽又は不当な申出によって、投稿者、運営者その他の第三者に損害が生じた場合、申出者が法令に基づく責任を負うことがあります。\n________________________________________\n第18条（通報者等に関する情報の取扱い）\n1.\t運営者は、通報、権利侵害に関する申出、異議申立てその他の手続を通じて取得した個人情報を、プライバシーポリシーに従って取り扱います。\n2.\t通報者又は申出者の氏名、連絡先、本人確認書類その他の情報は、次の場合を除き、対象となる投稿者又は第三者に開示しません。\n1.\t本人の同意がある場合\n2.\t申出への対応に必要であり、法令上認められる場合\n3.\t法令、裁判所の命令その他適法な手続に基づく場合\n4.\t人の生命、身体又は財産の保護のために必要な場合\n5.\tその他、法令により認められる場合\n3.\t投稿者に申出内容を通知する必要がある場合、運営者は、申出者の連絡先及び本人確認書類等を原則として開示せず、申出の理由及び対象部分を必要な範囲で伝えます。\n4.\t運営者は、本人確認書類について、確認後に保存する必要がある場合を除き、速やかに削除又はマスキングその他適切な処理を行います。\n5.\t通報及び申出に関する記録は、対応、紛争、不正利用防止及び法令遵守に必要な期間保存することがあります。\n________________________________________\n第19条（記録の保存及び発信者情報等への対応）\n1.\t運営者は、権利侵害、不正利用、通報又は紛争への対応に必要な範囲で、投稿コンテンツ、アカウント情報、アクセス記録、措置履歴その他の関連情報を保存することがあります。\n2.\t運営者は、裁判所、捜査機関その他の公的機関から、法令に基づいて情報の保存又は提供を求められた場合、適法な手続に従って対応します。\n3.\t発信者情報の開示を希望する者は、適用される法令及び手続に従って請求する必要があります。\n4.\t運営者は、正式な法的手続を経ない任意の請求について、請求者の本人確認、権利侵害の明白性、開示の必要性その他の事情を確認した上で対応を判断します。\n5.\t運営者は、法令上認められる場合を除き、本人の同意なく、利用者の個人情報を第三者へ任意に開示しません。\n6.\t運営者は、適法な開示請求又は証拠保全の要請を受けた場合、対象となる情報について通常の削除処理を一時的に停止することがあります。\n7.\t運営者が情報を保存していることは、請求者への開示が認められること又は情報が将来にわたり保存されることを保証するものではありません。\n________________________________________\n第20条（運営者の立場及び非保証）\n1.\t運営者は、通報又は権利侵害に関する申出について、利用規約、コミュニティガイドライン、提出された資料及び適用される法令等を踏まえて対応します。\n2.\t運営者は裁判所ではなく、当事者間の権利関係、違法性、損害賠償責任その他の法的問題を最終的に確定する立場にはありません。\n3.\t運営者は、すべての通報又は申出について、申出者が希望する措置を講じることを保証しません。\n4.\t運営者が投稿コンテンツを非表示又は削除しなかったことは、当該投稿が適法であり、又は権利侵害が存在しないことを保証するものではありません。\n5.\t運営者が投稿コンテンツを非表示又は削除したことは、当該投稿が違法であり、又は法的な権利侵害が確定したことを意味しません。\n6.\t当事者間で権利関係又は事実関係について重大な争いがある場合、運営者は、弁護士への相談、裁判所の手続その他の法的手段による解決を案内することがあります。\n7.\t本条は、運営者が法令上負うべき義務又は責任を免除するものではありません。\n________________________________________\n第21条（本ポリシーの変更）\n1.\t運営者は、法令の制定若しくは改廃、本サービスの内容変更、通報制度の変更その他必要がある場合、本ポリシーを変更することがあります。\n2.\t運営者は、本ポリシーを変更する場合、変更後の内容及び効力発生日を、本サービス上への掲載その他適切な方法により周知します。\n3.\t利用者に重大な影響又は不利益を与える変更については、緊急又はやむを得ない場合を除き、原則として効力発生日の30日前までに周知します。\n4.\t法令上又は利用規約上、利用者の同意が必要となる変更については、変更後の内容を適用する前に必要な同意を取得します。\n________________________________________\n第22条（お問い合わせ窓口）\n本ポリシー、通報、権利侵害に関する申出及び異議申立てに関するお問い合わせは、本サービス上のお問い合わせフォームからご連絡ください。\n運営者\n伊能龍之介\nサービス名\nSharemarium\nお問い合わせ方法\n本サービス上のお問い合わせフォーム\n________________________________________\n改定履歴\n2026年8月28日／バージョン1.2.0\n返信単位の報告機能及び管理者による返信単位の確認・削除手続を明確化しました。\n2026年8月27日／バージョン1.1.0\n返信に関する通報方法、対象の特定に必要な情報及び返信機能に対する措置を明確化しました。\n2026年8月17日／バージョン1.0.1\n投稿の通報機能とお問い合わせ窓口の使い分けを明確化しました。\n2026年7月25日／バージョン1.0.0\n本ポリシーを制定しました。\n________________________________________\n附則\n制定日\n2026年7月25日\n最終改定日\n2026年8月28日\nバージョン\n1.2.0\n運営者\n伊能龍之介''';\n\n  @override\n  Widget build(BuildContext context) {\n    final blocks = _parseBlocks(_policyText);\n\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.start,\n      children: [\n        for (final block in blocks) ...[\n          if (block.spacingBefore > 0) SizedBox(height: block.spacingBefore),\n          Padding(\n            padding: EdgeInsets.only(left: block.isBullet ? 12 : 0),\n            child: Text(\n              block.text,\n              style: block.style.copyWith(color: Colors.white),\n            ),\n          ),\n        ],\n        const SizedBox(height: 40),\n      ],\n    );\n  }\n\n  static List<_PolicyBlock> _parseBlocks(String source) {\n    final blocks = <_PolicyBlock>[];\n    var nextLineIsSectionHeading = false;\n    const labels = {'運営者', 'サービス名', 'お問い合わせ方法', '制定日', '最終改定日', 'バージョン'};\n\n    for (final rawLine in source.split('\\n')) {\n      final line = rawLine.trim();\n      if (line.isEmpty) {\n        continue;\n      }\n      if (RegExp(r'^_+$').hasMatch(line)) {\n        nextLineIsSectionHeading = true;\n        continue;\n      }\n\n      if (blocks.isEmpty) {\n        blocks.add(\n          _PolicyBlock(text: line, style: _titleStyle, spacingBefore: 0),\n        );\n      } else if (nextLineIsSectionHeading) {\n        nextLineIsSectionHeading = false;\n        blocks.add(\n          _PolicyBlock(text: line, style: _headingStyle, spacingBefore: 20),\n        );\n      } else if (labels.contains(line)) {\n        blocks.add(\n          _PolicyBlock(text: line, style: _labelStyle, spacingBefore: 10),\n        );\n      } else if (line.startsWith('•')) {\n        blocks.add(\n          _PolicyBlock(\n            text: line,\n            style: _bodyStyle,\n            spacingBefore: 0,\n            isBullet: true,\n          ),\n        );\n      } else {\n        blocks.add(\n          _PolicyBlock(text: line, style: _bodyStyle, spacingBefore: 6),\n        );\n      }\n    }\n\n    return blocks;\n  }\n}\n\nclass _PolicyBlock {\n  const _PolicyBlock({\n    required this.text,\n    required this.style,\n    required this.spacingBefore,\n    this.isBullet = false,\n  });\n\n  final String text;\n  final TextStyle style;\n  final double spacingBefore;\n  final bool isBullet;\n}\n",
  "external-transmission": "import 'package:flutter/material.dart';\n\nclass ExternalTransmissionScreen extends StatelessWidget {\n  const ExternalTransmissionScreen({super.key, this.onClose});\n\n  final VoidCallback? onClose;\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      backgroundColor: Colors.black,\n      appBar: AppBar(\n        backgroundColor: Colors.black,\n        foregroundColor: Colors.white,\n        surfaceTintColor: Colors.transparent,\n        title: const Text('外部送信に関する公表事項'),\n        leading: IconButton(\n          icon: const Icon(Icons.close),\n          onPressed: onClose ?? () => Navigator.of(context).pop(),\n        ),\n      ),\n      body: const SafeArea(\n        child: SingleChildScrollView(\n          padding: EdgeInsets.symmetric(horizontal: 24, vertical: 20),\n          child: _ExternalTransmissionContent(),\n        ),\n      ),\n    );\n  }\n}\n\nclass _ExternalTransmissionContent extends StatelessWidget {\n  const _ExternalTransmissionContent();\n\n  static const _titleStyle = TextStyle(\n    fontSize: 18,\n    fontWeight: FontWeight.w900,\n    height: 1.5,\n  );\n\n  static const _headingStyle = TextStyle(\n    fontSize: 15,\n    fontWeight: FontWeight.w700,\n    height: 1.7,\n  );\n\n  static const _subheadingStyle = TextStyle(\n    fontSize: 13,\n    fontWeight: FontWeight.w700,\n    height: 1.7,\n  );\n\n  static const _minorHeadingStyle = TextStyle(\n    fontSize: 13,\n    fontWeight: FontWeight.w600,\n    height: 1.7,\n    color: Colors.white,\n  );\n\n  static const _bodyStyle = TextStyle(\n    fontSize: 13,\n    height: 1.9,\n    color: Colors.white,\n  );\n\n  static const String _disclosureText = r'''# Sharemarium 外部送信に関する公表事項\n\n伊能龍之介（以下「運営者」といいます。）は、運営者が提供する読書レビューSNS「Sharemarium」（以下「本サービス」といいます。）において、電気通信事業法その他の法令に基づき、利用者の端末から外部事業者へ送信される情報について、以下のとおり公表します。\n\n---\n\n## 1. 外部送信について\n\n本サービスでは、次の目的のため、利用者の端末に保存された情報又は利用者の端末で生成された情報が、外部事業者へ送信されることがあります。\n\n* 本サービスの提供及び運営\n* 利用者の登録及び認証\n* 不正登録及び不正アクセスの防止\n* 利用状況の分析\n* サービス品質及び利便性の向上\n* 不具合及び障害の調査\n* セキュリティ対策\n* 広告の配信及び広告効果の測定\n* 不正な広告表示又はクリックの防止\n* その他、本サービスの適切かつ安全な運営に必要な目的\n\n運営者は、外部送信によって取得した情報を、本公表事項及びプライバシーポリシーに記載した目的の範囲で利用します。\n\n外部事業者が受信した情報については、当該外部事業者の利用規約、プライバシーポリシーその他の規程に基づいて取り扱われる場合があります。\n\n---\n\n## 2. 認証、データベース、同意履歴、お問い合わせ及び退会処理\n\n### 情報を取り扱う事業者\n\nSupabase, Inc.\n\n### 利用するサービス\n\n* Supabase Auth\n* Supabase Database\n* Supabase Edge Functions\n\n### 送信される情報\n\n* 氏名\n* 生年月日\n* メールアドレス\n* 電話番号\n* ユーザーネーム及び公開用のユーザーID\n* UIDその他のアカウント識別子\n* Google、X、Facebook、Apple、Discordその他の認証providerに関する情報\n* 外部サービス上の利用者識別子\n* アカウントの作成日時\n* 最終ログイン日時\n* 認証要求、認証結果及び認証用トークンに関する情報\n* IPアドレス\n* ブラウザ、OS、端末及び使用言語に関する情報\n* アクセス日時、通信記録、エラー及びセキュリティログ\n* プロフィール、レビュー、評価、My 本棚、お気に入り、「読みたい！」作品その他利用者が本サービスへ保存する情報\n* ユーザー検索のために入力したユーザー名又は公開用のユーザーID\n* リアクション、「読みたい！」の対象投稿、登録数及び登録者、フォロー、フォローリクエスト、フォロー中の登録利用者による新規投稿、ブロック並びにアプリ内通知に関する情報\n* 返信本文、返信先となる投稿又は返信の識別情報、返信の親子関係、返信日時、ネタバレ設定及び返信の表示状態\n* 返信機能、「読みたい！」、お気に入りの登録上限、ページカラーの選択範囲その他の限定機能を利用できるかを判定するための利用権限、試験利用又は個別許可に関する情報\n* ページカラーの解禁判定に用いるレビュー投稿件数、解禁可能数、選択して解禁した色及び解禁日時\n* 通報理由、任意の補足、対象投稿又は対象返信の識別情報及び記録、対応状況、投稿若しくは返信の削除及びアカウント停止等の措置に関する情報\n* 利用規約、プライバシーポリシー、コミュニティガイドライン、権利侵害・通報ポリシー及び外部送信に関する公表事項のバージョン並びに同意日時\n* お問い合わせ種別、返信先メールアドレス、件名及びお問い合わせ内容\n* 退会要求及び退会処理に必要な情報\n* 退会後に90日間保存する元の利用者識別子、ユーザー名、公開用のユーザーID、氏名、生年月日、メールアドレス、電話番号、認証方式、退会種別、退会日時、削除処理の成否、削除実行者、必要最小限の対応履歴及び法的保存措置に関する情報\n* 個人情報変更用パスワードのハッシュ値、照合結果及び再設定要求に関する情報\n* 不正利用の検知及び本サービスの安全な運営に必要な情報\n\n運営者は、利用者のGoogle、X、Facebook、Apple又はDiscordアカウントのパスワードを取得しません。認証用トークンは、ログイン状態の維持、本人確認及び認証処理に必要な範囲で取り扱われます。個人情報変更用パスワードは復元できないハッシュ値として保存されます。\n\n### 運営者における利用目的\n\n* 利用登録、ログイン及び利用者認証\n* 氏名、生年月日及び電話番号を含む登録情報の保存及び管理\n* 生年月日に基づく年齢確認及び青少年保護\n* 電話番号認証を導入した場合の電話番号確認\n* アカウント、プロフィール、投稿、My 本棚、お気に入り及び「読みたい！」作品等の作成、保存及び表示\n* ユーザー名及び公開用のユーザーIDによるユーザー検索\n* 返信の投稿、スレッド表示、ネタバレ表示、閲覧権限の制御、リアクション及び「読みたい！」の通知、フォロー中の登録利用者による新規投稿通知、お気に入りの登録上限、レビュー投稿件数に応じたページカラーの解禁及び選択範囲並びに限定機能の利用権限の判定\n* 規約及びポリシーへの同意又は確認状況の記録\n* お問い合わせ、通報、権利侵害に関する申出及び開示等の請求への対応並びに管理者による投稿削除及びアカウント停止等の措置\n* 利用者による退会及びアカウント削除、退会処理の確認並びに退会記録の90日後の自動削除\n* 裁判所、警察その他の公的機関からの適法な照会、具体的な紛争、通報、権利侵害又は不正利用に対応するための法的保存措置\n* 不正登録、不正ログイン、スパム、ボットその他の不正利用の検知及び防止\n* 障害調査、ログ管理、セキュリティ確保及び本サービスの運営\n\n### 外部事業者における利用目的\n\n* 認証、データベース及びEdge Functionsの提供\n* データの保存、処理、バックアップ及び配信\n* サービスの維持、障害対応、セキュリティ確保及び不正利用防止\n* Supabaseの利用規約、プライバシーポリシー及びデータ処理契約に定める目的\n\nSupabaseのプロジェクトデータは運営者が選択したリージョンで処理されます。また、認証、ログ、バックアップ、Edge Functions、サポートその他の処理が日本国外で行われる場合があります。\n\n電話番号認証を導入する場合、SMSの配信又は不正利用防止を行う事業者の名称、送信される情報及び利用目的を、導入前に本公表事項へ追記します。\n\n---\n\n## 3. 書籍情報の検索及び取得\n\n### 情報を取り扱う事業者\n\n楽天グループ株式会社\n\n### 送信される情報\n\n* 利用者が書籍検索欄へ入力した検索語\n* 書籍のISBNその他の書籍識別情報\n* 検索結果のページ番号、取得件数、ジャンル及び並び順\n* IPアドレス\n* ブラウザ、OS、端末、アクセス日時その他通信に伴い送信される情報\n\n### 運営者における利用目的\n\n* 題名、著者名又は出版社名による書籍検索結果の表示\n* 人気作品、新着及び洋書の表示\n* 書籍情報、書影、評価及びレビュー件数の取得\n\n### 外部事業者における利用目的\n\n* 楽天ウェブサービスの提供、維持及び不正利用防止\n* 当該事業者の利用規約及びプライバシーポリシーに定める目的\n\n運営者は、利用者が入力した検索語を利用者別の検索履歴として本サービスのデータベースへ保存しません。\n\n---\n\n## 3-1. 楽天アフィリエイトによる購入先リンク\n\n### 情報を取り扱う事業者\n\n楽天グループ株式会社\n\n### 送信される情報\n\n利用者が書籍詳細の楽天リンクを選択した場合、利用者の端末から楽天ブックスへ、次の情報が送信されることがあります。\n\n* 該当書籍の商品URL\n* 楽天アフィリエイトの識別タグを含むリンク情報\n* IPアドレス\n* ブラウザ、OS、端末、リファラー、アクセス日時その他楽天ブックスへの遷移に伴い送信される情報\n\n運営者は、楽天アフィリエイトリンクを通じて、利用者の氏名、メールアドレス、電話番号、SharemariumのユーザーID、投稿本文又は個別の購入履歴を楽天グループ株式会社へ意図的に送信しません。\n\n### 利用目的\n\n* 利用者が楽天ブックス上で書籍を確認又は購入できるようにするため\n* 楽天アフィリエイトに基づく紹介料の計測及び不正利用防止のため\n* 楽天アフィリエイトの提供、維持及び同プログラムの規約又はプライバシーポリシーに定める目的\n\n---\n\n## 4. 書影画像の最適化及び配信\n\n### 情報を取り扱う事業者\n\nimages.weserv.nlの運営者\n\n### 送信される情報\n\n* 楽天ウェブサービスから取得した書影画像のURL\n* IPアドレス\n* ブラウザ、OS、端末、リファラー、アクセス日時その他画像取得に伴い送信される情報\n\n### 利用目的\n\n* 書影画像の取得、サイズ調整、キャッシュ及び配信\n* 表示速度及び互換性の向上\n* 障害対応、セキュリティ確保及び不正利用防止\n\n---\n\n## 5. Webサイトのホスティング及び配信\n\n### 情報を取り扱う事業者\n\nVercel Inc.\n\n### 送信される情報\n\n* IPアドレス\n* 閲覧したURL、リファラー、アクセス日時及びHTTPリクエスト情報\n* ブラウザ、OS、端末及び使用言語に関する情報\n* Cookieその他の識別子\n* エラー、動作状況、セキュリティ及び通信ログ\n\n### 利用目的\n\n* 本サービスのWebページ及び静的ファイルの配信\n* 通信の高速化、障害対応及びセキュリティ確保\n* 不正アクセスその他の不正利用の検知及び防止\n\n---\n\n## 6. Webフォントの取得\n\n### 情報を取り扱う事業者\n\nGoogle LLC\n\n### 送信される情報\n\n* IPアドレス\n* ブラウザ、OS、端末、リファラー及びアクセス日時に関する情報\n* フォントファイルの取得に伴い送信される情報\n\n### 利用目的\n\n* 本サービス上で使用するフォントの取得及び表示\n* フォント配信サービスの維持、セキュリティ確保及び改善\n\n---\n\n## 7. アクセス解析\n\n### 情報を取り扱う事業者\n\nGoogle LLC\n\n本項は、Googleのアクセス解析機能を本サービスへ導入した場合に適用されます。\n\n### 送信される情報\n\n* Cookieその他の識別子\n* 利用者又は端末を識別するための識別子\n* IPアドレス\n* ブラウザの種類及びバージョン\n* OSの種類及びバージョン\n* 端末の種類及び設定\n* 使用言語\n* アクセス日時\n* 閲覧したページ又は画面\n* ページのタイトル及びURL\n* リファラー（参照元URL）\n* 画面遷移\n* クリックその他の操作履歴\n* 検索及び絞り込み等の利用状況\n* セッションの継続時間\n* エラー及び動作状況\n* IPアドレス等から推定される国又はおおよその地域\n* その他、利用状況の分析に必要な情報\n\n運営者は、電話番号、レビュー本文、通報本文その他利用者を直接特定し得る情報を、アクセス解析のための情報として意図的に送信しないよう設定及び運用します。\n\n### 運営者における利用目的\n\n* 本サービスの利用状況の把握\n* 閲覧数及び利用傾向の分析\n* 機能及び画面構成の改善\n* 不具合及び障害の調査\n* 本サービスの品質及び利便性の向上\n* 統計情報の作成\n\n### 外部事業者における利用目的\n\n* アクセス解析機能の提供\n* 利用状況の測定及び分析\n* サービスの提供、維持及び改善\n* 不正利用及びセキュリティ上の問題の検知\n* 当該事業者の利用規約及びプライバシーポリシーに定める目的\n\n---\n\n## 8. 広告配信及び広告効果測定\n\n### 現在の広告配信事業者及びサービス\n\n忍者ツールズ株式会社（忍者AdMax）\n\n本サービスでは、Webサイトのホーム画面、書籍検索結果及びタイムライン等の広告対象枠に忍者AdMaxの広告を掲載します。広告表示の対象となるのは、広告を非表示とする利用権限がない利用者です。実際の表示位置及び件数は、公開コンテンツの有無等によって変動します。現行のネイティブアプリには当該広告タグを読み込みません。\n\n### 送信される情報\n\n広告タグが読み込まれた場合、利用者の端末から忍者ツールズ株式会社及び広告配信に関与する事業者へ、次の情報が送信又は取得されることがあります。\n\n* 閲覧したページのURL、リファラー（参照元URL）及びアクセス日時\n* IPアドレス、通信に関するリクエスト情報\n* ブラウザの種類及びバージョン、OS、端末の機種その他の端末情報\n* Cookieその他の識別子（事業者又は提携先が利用する場合）\n* 広告の表示状況、表示回数、クリックその他の広告操作情報\n* 広告配信、効果測定及び不正利用防止に必要な情報\n\n上記は事業者が公表する情報と現在の広告タグの用途に基づく説明です。実際の通信先・送信項目は利用環境及び配信される広告によって異なる場合があります。本サービスは広告配信のために、利用者の氏名、メールアドレス、電話番号、Sharemariumの認証トークン又はレビュー本文を、広告タグのパラメータとして意図的に付加しません。\n\n### 運営者における利用目的\n\n* 本サービスの無料提供を支えるための広告掲載及び広告収益の集計\n* 広告配信状況、表示回数及び広告効果の把握\n* 広告の不正表示、不正クリックその他の不正利用の防止\n* 本サービスの運営及び改善\n\n### 忍者ツールズ株式会社及び広告配信に関与する事業者における利用目的\n\n* 広告の配信、選定、最適化及び表示回数の調整\n* 広告効果の測定、統計分析及び広告配信サービスの改善\n* 不正なクリックその他の不正行為の検出及び防止\n* 各事業者が公表するプライバシーポリシー、Cookieポリシー等に記載された目的\n\n### Cookie等の制限と確認先\n\nCookie等の取得を制限する場合、ブラウザの設定を変更できる場合があります。広告のパーソナライズを制限しても広告そのものが表示される場合があります。提携先事業者が個別に提供するオプトアウトの方法については、その事業者の案内を確認してください。\n\n* 忍者ツールズ株式会社のCookieポリシー：https://corp.ninja.co.jp/privacy/cookie/\n* 業務提携先及びその公表情報：https://corp.ninja.co.jp/privacy/tieup/\n* 忍者AdMax利用規約：https://www.ninja.co.jp/rule/admax\n\n### 将来Google広告を利用する場合\n\nGoogle LLCが提供するGoogle AdSenseによる広告配信は、現在の本サービスでは稼働していません。将来、Googleの広告配信又は広告効果測定を導入する場合は、送信される情報、送信先及び利用目的を実態に即して改めて公表し、必要な同意等を確認した上で有効化します。Googleによる広告のパーソナライズ設定は https://adssettings.google.com/ を参照してください。\n\n---\n\n## 9. Googleアカウントによるログイン及び不正利用防止\n\n### 情報を取り扱う事業者\n\nGoogle LLC\n\n本項は、本サービスで提供するGoogleアカウントによる登録及びログインに適用されます。\n\n### 送信される情報\n\n* Googleアカウントの識別子\n* メールアドレス\n* 表示名\n* プロフィール画像\n* 利用者が提供を許可した情報\n* 認証用の識別子及びトークン\n* IPアドレス\n* ブラウザ、OS及び端末に関する情報\n* 登録又はログインを行った日時\n* 不正利用の検知に必要な情報\n\n#### 不正登録等の防止機能を利用する場合\n\n* IPアドレス\n* Cookieその他の識別子\n* ブラウザ、OS及び端末に関する情報\n* 使用言語\n* アクセス日時\n* 閲覧ページ及びリファラー\n* クリックその他の操作情報\n* 登録又は認証の要求に関する情報\n* スパム、ボット、自動操作その他の不正利用の判定に必要な情報\n\n運営者は、利用者のGoogleアカウントのパスワードを取得しません。\n\n### 運営者における利用目的\n\n* 本サービスへの利用登録\n* 利用者の認証及びログイン\n* 一人の利用者による大量のアカウント作成の防止\n* なりすまし及び不正ログインの防止\n* ボット及び自動操作の検知\n* スパム及び不正登録の防止\n* アカウントの安全管理\n* 利用規約違反及び不正利用への対応\n* 本サービス及び利用者の安全の確保\n\n### 外部事業者における利用目的\n\n* Googleアカウントによるログイン及び認証機能の提供\n* 認証要求の処理\n* アクセスが人によるものか、自動的なプログラムによるものかの判定\n* 不正アクセス、スパム、ボット及び不正利用の検知及び防止\n* サービスの提供、維持、保護及び改善\n* 当該事業者の利用規約及びプライバシーポリシーに定める目的\n\n---\n\n## 10. Xアカウントによるログイン\n\n### 情報を取り扱う事業者\n\nX Corp.\n\n### 送信される情報\n\n* Xアカウントの識別子\n* X上のユーザー名\n* 表示名\n* プロフィール画像\n* メールアドレスその他利用者が提供を許可した情報\n* 認証要求及び認証結果に関する情報\n* 認証用の識別子及びトークン\n* IPアドレス\n* ブラウザ、OS及び端末に関する情報\n* 登録又はログインを行った日時\n* セキュリティ及び不正利用防止に必要な情報\n\n運営者は、利用者のXアカウントのパスワードを取得しません。\n\n### 運営者における利用目的\n\n* 本サービスへの利用登録\n* 利用者の認証及びログイン\n* アカウントの作成及び管理\n* なりすまし及び不正ログインの防止\n* 利用規約違反及び不正利用への対応\n\n### 外部事業者における利用目的\n\n* ログイン及び認証機能の提供\n* 認証要求の処理\n* サービスの運営、保護及び改善\n* 不正アクセス及び不正利用の検知及び防止\n* 当該事業者の利用規約及びプライバシーポリシーに定める目的\n\n---\n\n## 11. Facebook、Apple及びDiscordアカウントによるログイン\n\n### 情報を取り扱う事業者\n\nMeta Platforms, Inc.、Apple Inc.及びDiscord Inc.\n\n本項は、各ログイン方法が実際に有効化された場合に限って適用されます。現時点では、これらのログイン方法は提供していません。\n\n### 送信される情報\n\n* 各外部サービスが本サービス向けに発行する利用者識別子\n* 認証要求、認証結果及び認証コードに関する情報\n* 認証用の識別子及びトークン\n* 表示名、ユーザー名及びプロフィール画像（利用者が提供を許可した場合）\n* メールアドレス（利用者が提供を許可し、外部サービスから提供された場合）\n* IPアドレス\n* ブラウザ、OS及び端末に関する情報\n* 登録又はログインを行った日時\n* セキュリティ及び不正利用防止に必要な情報\n\n運営者は、利用者のFacebook、Apple又はDiscordアカウントのパスワードを取得しません。Appleのメールを非公開にする機能等により、外部サービスが中継用又は代替のメールアドレスを提供する場合があります。\n\n### 運営者における利用目的\n\n* 本サービスへの利用登録\n* 利用者の認証及びログイン\n* アカウントの作成及び管理\n* なりすまし及び不正ログインの防止\n* 利用規約違反及び不正利用への対応\n\n### 外部事業者における利用目的\n\n* Facebook、Apple又はDiscordによるログイン及び認証機能の提供\n* 認証要求の処理\n* サービスの運営、保護及び改善\n* 不正アクセス及び不正利用の検知及び防止\n* 当該事業者の利用規約及びプライバシーポリシーに定める目的\n\n---\n\n## 12. Cookie等の無効化及び広告設定\n\n利用者は、ブラウザ又は端末の設定により、Cookieの保存を拒否し、保存済みのCookieを削除し、又は広告識別子の利用を制限できる場合があります。\n\nまた、広告配信事業者が提供する広告設定を利用して、広告のパーソナライズを制限又は無効化できる場合があります。\n\nCookie等を無効化した場合であっても、広告自体は表示される場合があります。\n\nCookie等を無効化した場合、次の機能の全部又は一部が正常に利用できなくなることがあります。\n\n* ログイン状態の維持\n* 利用者認証\n* セキュリティ機能\n* 設定内容の保存\n* アクセス解析\n* 広告の表示及び表示回数の調整\n* その他、Cookie等を必要とする機能\n\n---\n\n## 13. 外部事業者における情報の取扱い\n\n外部事業者へ送信された情報は、各外部事業者の利用規約、プライバシーポリシー、Cookieポリシーその他の規程に従って取り扱われます。\n\n外部事業者は、日本国外において情報を保存又は処理する場合があります。\n\n運営者は、外部事業者のサービスを利用する場合、利用目的、送信される情報、安全管理の状況その他の事情を考慮し、適切な事業者及びサービスを選定するよう努めます。\n\n---\n\n## 14. 本公表事項の変更\n\n運営者は、法令の制定若しくは改廃、本サービスの内容変更、利用する外部サービスの追加、変更若しくは廃止その他必要がある場合、本公表事項を変更することがあります。\n\n変更後の内容及び効力発生日は、本サービス上への掲載その他適切な方法により公表します。\n\n利用者に重大な影響又は不利益を与える変更については、緊急又はやむを得ない場合を除き、原則として効力発生日の30日前までに公表又は通知します。\n\n法令上、利用者の同意が必要となる変更又は外部送信については、変更後の取扱いを開始する前に、運営者所定の方法により必要な同意を取得します。\n\n---\n\n## 15. お問い合わせ\n\n本公表事項又は外部送信に関するお問い合わせは、本サービス上のお問い合わせフォームからご連絡ください。\n\n**運営者**\n伊能龍之介\n\n**サービス名**\nSharemarium\n\n**お問い合わせ方法**\n本サービス上のお問い合わせフォーム\n\n---\n\n## 改定履歴\n\n**2026年10月17日／バージョン1.11.0**\n\n忍者AdMaxの広告掲載対象をホーム画面、書籍検索結果及びタイムライン等として明確化しました。現在提供していない定期購入サービスに関する表現を削除し、限定機能の判定に用いる情報を利用権限、試験利用又は個別許可に関する情報として整理しました。また、レビュー投稿件数に応じたページカラーの解禁に用いる情報及び利用目的を明確化しました。\n\n**2026年10月12日／バージョン1.10.0**\n\n書籍の購入先リンクをAmazonアソシエイトから楽天アフィリエイトへ変更し、リンク先及び外部送信情報の説明を更新しました。\n忍者ツールズ株式会社（忍者AdMax）への広告関連情報の外部送信、目的、Cookie等の取扱い及びGoogle AdSenseの非稼働状態を明示しました。\n\n**2026年9月4日／バージョン1.9.0**\n\nAmazonアソシエイト・プログラムによる書籍の購入先リンクについて、送信される情報及び利用目的を追記しました。\n\n**2026年9月2日／バージョン1.8.0**\n「読みたい！」作品、投稿別の登録情報、登録者一覧及び通知について、Supabaseへ送信する情報と利用目的を明確化しました。\n\n**2026年8月30日／バージョン1.7.0**\n退会者の本人確認情報及び削除監査情報をSupabaseへ送信して90日間保存すること、自動削除及び法的保存措置の利用目的を明確化しました。\n\n**2026年8月30日／バージョン1.6.0**\n限定機能の利用権限に応じたお気に入り登録上限及びページカラー選択範囲の判定について、Supabaseへ送信する情報と利用目的を明確化しました。\n\n**2026年8月30日／バージョン1.5.0**\nGoogleアカウント認証の提供開始に合わせ、Google LLCへ送信する情報及び利用目的の適用状態を更新しました。\n\n**2026年8月28日／バージョン1.4.0**\n返信のネタバレ設定及びフォロー中の登録利用者による新規投稿通知について、Supabaseへ送信する情報と利用目的を明確化しました。\n\n**2026年8月28日／バージョン1.3.0**\n返信単位の通報機能について、Supabaseへ送信する対象返信の識別情報、返信本文の記録及び管理者の対応情報を明確化しました。\n\n**2026年8月27日／バージョン1.2.0**\n返信本文、返信関係、通知及び限定機能の利用権限について、Supabaseへ送信する情報及び利用目的を明確化しました。\n\n**2026年8月19日／バージョン1.1.0**\nSupabaseへ送信する登録情報、ユーザー検索に関する情報及び利用目的を明確化しました。\n\n**2026年7月25日／バージョン1.0.0**\n本公表事項を制定しました。\n\n---\n\n## 附則\n\n**制定日**\n2026年7月25日\n\n**最終改定日**\n2026年10月17日\n\n**バージョン**\n1.11.0\n\n**運営者**\n伊能龍之介''';\n\n  @override\n  Widget build(BuildContext context) {\n    final blocks = _parseBlocks(_disclosureText);\n\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.start,\n      children: [\n        for (final block in blocks) ...[\n          if (block.spacingBefore > 0) SizedBox(height: block.spacingBefore),\n          Padding(\n            padding: EdgeInsets.only(left: block.leftPadding),\n            child: Text(\n              block.text,\n              style: block.style.copyWith(color: Colors.white),\n            ),\n          ),\n        ],\n        const SizedBox(height: 40),\n      ],\n    );\n  }\n\n  static List<_DisclosureBlock> _parseBlocks(String source) {\n    final blocks = <_DisclosureBlock>[];\n    var previousLineWasEmpty = false;\n\n    for (final rawLine in source.split('\\n')) {\n      final line = rawLine.trim();\n      if (line.isEmpty) {\n        previousLineWasEmpty = true;\n        continue;\n      }\n      if (line == '---') {\n        previousLineWasEmpty = true;\n        continue;\n      }\n\n      final spacing = previousLineWasEmpty ? 10.0 : 2.0;\n      previousLineWasEmpty = false;\n\n      if (line.startsWith('# ')) {\n        blocks.add(\n          _DisclosureBlock(\n            text: line.substring(2),\n            style: _titleStyle,\n            spacingBefore: blocks.isEmpty ? 0 : 20,\n          ),\n        );\n      } else if (line.startsWith('## ')) {\n        blocks.add(\n          _DisclosureBlock(\n            text: line.substring(3),\n            style: _headingStyle,\n            spacingBefore: blocks.isEmpty ? 0 : 20,\n          ),\n        );\n      } else if (line.startsWith('### ')) {\n        blocks.add(\n          _DisclosureBlock(\n            text: line.substring(4),\n            style: _subheadingStyle,\n            spacingBefore: 12,\n          ),\n        );\n      } else if (line.startsWith('#### ')) {\n        blocks.add(\n          _DisclosureBlock(\n            text: line.substring(5),\n            style: _minorHeadingStyle,\n            spacingBefore: 10,\n            leftPadding: 8,\n          ),\n        );\n      } else if (line.startsWith('**') && line.endsWith('**')) {\n        blocks.add(\n          _DisclosureBlock(\n            text: line.substring(2, line.length - 2),\n            style: _subheadingStyle,\n            spacingBefore: spacing,\n          ),\n        );\n      } else if (line.startsWith('* ')) {\n        blocks.add(\n          _DisclosureBlock(\n            text: '• ${line.substring(2).replaceAll('**', '')}',\n            style: _bodyStyle,\n            spacingBefore: 0,\n            leftPadding: 12,\n          ),\n        );\n      } else {\n        blocks.add(\n          _DisclosureBlock(\n            text: line.replaceAll('**', ''),\n            style: _bodyStyle,\n            spacingBefore: spacing,\n          ),\n        );\n      }\n    }\n\n    return blocks;\n  }\n}\n\nclass _DisclosureBlock {\n  const _DisclosureBlock({\n    required this.text,\n    required this.style,\n    required this.spacingBefore,\n    this.leftPadding = 0,\n  });\n\n  final String text;\n  final TextStyle style;\n  final double spacingBefore;\n  final double leftPadding;\n}\n"
};

